  getHealthChecks(serviceName?: string): Promise<HealthCheck[]>;
  getLatestHealthStatus(): Promise<{ [serviceName: string]: HealthCheck }>;

  // ============================================
  // SPRINT 1 - Async Processing & Export Tracking
  // ============================================

