                          </Badge>
                          <span className="text-sm font-medium text-foreground">76% Confidence</span>
                        </div>
                      </div>
                      <HelpCircle className="h-4 w-4 text-blue-500" />
                    </div>
                  </div>
                </div>

                {/* Interactive Fact-Check Results */}
