                                }`} />
                                <div>
                                  <h3 className="font-medium">{usecase.name}</h3>
                                  <p className="text-sm text-muted-foreground">{usecase.desc}</p>
                                </div>
                              </div>
                            </div>
                          ))}
                        </div>
                      </div>
