import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { useForm } from 'react-hook-form';
import { useToast } from '@/hooks/use-toast';
import { apiRequest } from '@/lib/queryClient';
import { 
  Users, 
  Plus, 
  Edit, 
  Trash2, 
  Crown, 
  Shield,
  Building,
  UserPlus,
  Settings
} from 'lucide-react';

interface OrganizationManagerProps {
  userRole: string;
}

export function OrganizationManager({ userRole }: OrganizationManagerProps) {
  const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false);
  const [selectedOrganization, setSelectedOrganization] = useState<string>('');
  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Fetch organizations
  const { data: organizations, isLoading } = useQuery({
    queryKey: ['/api/organizations'],
    enabled: userRole === 'super_admin',
    throwOnError: false,
    retry: false
  });

  // Fetch organization members for selected organization
  const { data: members } = useQuery({
    queryKey: ['/api/organizations', selectedOrganization, 'members'],
    enabled: !!selectedOrganization && userRole === 'super_admin',
    throwOnError: false,
    retry: false
  });

  // Create organization form
  const form = useForm({
    defaultValues: {
      name: '',
      description: '',
      plan: 'free'
    }
  });

  // Create organization mutation
  const createOrganizationMutation = useMutation({
    mutationFn: async (data: any) => {
      return await apiRequest('/api/organizations', {
        method: 'POST',
        body: JSON.stringify(data)
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/organizations'] });
      setIsCreateDialogOpen(false);
      form.reset();
      toast({
        title: "Organization created",
        description: "New organization has been created successfully.",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to create organization",
        variant: "destructive",
      });
    }
  });

  const onCreateSubmit = (data: any) => {
    createOrganizationMutation.mutate(data);
  };

  const getRoleIcon = (role: string) => {
    switch (role) {
      case 'super_admin': return <Crown className="h-4 w-4 text-purple-500" />;
      case 'admin': return <Shield className="h-4 w-4 text-blue-500" />;
      case 'manager': return <Users className="h-4 w-4 text-green-500" />;
      default: return <Users className="h-4 w-4 text-gray-500" />;
    }
  };

  const getRoleColor = (role: string) => {
    switch (role) {
      case 'super_admin': return 'text-purple-600 bg-purple-50 border-purple-200';
      case 'admin': return 'text-blue-600 bg-blue-50 border-blue-200';
      case 'manager': return 'text-green-600 bg-green-50 border-green-200';
      default: return 'text-gray-600 bg-gray-50 border-gray-200';
    }
  };

  const getPlanColor = (plan: string) => {
    switch (plan) {
      case 'enterprise': return 'text-purple-600 bg-purple-50 border-purple-200';
      case 'pro': return 'text-blue-600 bg-blue-50 border-blue-200';
      case 'free': return 'text-gray-600 bg-gray-50 border-gray-200';
      default: return 'text-gray-600 bg-gray-50 border-gray-200';
    }
  };

  if (userRole !== 'super_admin') {
    return (
      <Card data-testid="organization-access-denied">
        <CardHeader>
          <CardTitle>Organization Management</CardTitle>
          <CardDescription>Access denied - Super administrator privileges required</CardDescription>
        </CardHeader>
      </Card>
    );
  }

  return (
    <div className="space-y-6" data-testid="organization-manager">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-semibold">Organization Management</h3>
          <p className="text-sm text-muted-foreground">
            Manage organizations, teams, and member permissions
          </p>
        </div>

        <Dialog open={isCreateDialogOpen} onOpenChange={setIsCreateDialogOpen}>
          <DialogTrigger asChild>
            <Button data-testid="create-organization-button">
              <Plus className="h-4 w-4 mr-2" />
              Create Organization
            </Button>
          </DialogTrigger>
          <DialogContent data-testid="create-organization-dialog">
            <DialogHeader>
              <DialogTitle>Create New Organization</DialogTitle>
              <DialogDescription>
                Add a new organization to the platform
              </DialogDescription>
            </DialogHeader>
            <Form {...form}>
              <form onSubmit={form.handleSubmit(onCreateSubmit)} className="space-y-4">
                <FormField
                  control={form.control}
                  name="name"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Organization Name</FormLabel>
                      <FormControl>
                        <Input 
                          placeholder="Acme Corporation" 
                          {...field}
                          data-testid="input-organization-name"
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="description"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Description</FormLabel>
                      <FormControl>
                        <Input 
                          placeholder="Brief description of the organization" 
                          {...field}
                          data-testid="input-organization-description"
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="plan"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Plan</FormLabel>
                      <Select onValueChange={field.onChange} defaultValue={field.value}>
                        <FormControl>
                          <SelectTrigger data-testid="select-organization-plan">
                            <SelectValue placeholder="Select a plan" />
                          </SelectTrigger>
                        </FormControl>
                        <SelectContent>
                          <SelectItem value="free">Free</SelectItem>
                          <SelectItem value="pro">Pro</SelectItem>
                          <SelectItem value="enterprise">Enterprise</SelectItem>
                        </SelectContent>
                      </Select>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <div className="flex justify-end space-x-2">
                  <Button 
                    type="button" 
                    variant="outline" 
                    onClick={() => setIsCreateDialogOpen(false)}
                  >
                    Cancel
                  </Button>
                  <Button 
                    type="submit" 
                    disabled={createOrganizationMutation.isPending}
                    data-testid="submit-create-organization"
                  >
                    {createOrganizationMutation.isPending ? 'Creating...' : 'Create Organization'}
                  </Button>
                </div>
              </form>
            </Form>
          </DialogContent>
        </Dialog>
      </div>

      {/* Organizations Table */}
      <Card data-testid="organizations-table">
        <CardHeader>
          <CardTitle>Organizations</CardTitle>
          <CardDescription>
            All organizations in the platform
          </CardDescription>
        </CardHeader>
        <CardContent>
          {isLoading ? (
            <div className="space-y-2">
              {[...Array(5)].map((_, i) => (
                <div key={i} className="h-12 bg-gray-100 dark:bg-gray-800 rounded animate-pulse" />
              ))}
            </div>
          ) : organizations?.organizations?.length > 0 ? (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Organization</TableHead>
                  <TableHead>Plan</TableHead>
                  <TableHead>Members</TableHead>
                  <TableHead>Created</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {organizations.organizations.map((org: any) => (
                  <TableRow 
                    key={org.id} 
                    className={selectedOrganization === org.id ? 'bg-blue-50 dark:bg-blue-900/20' : ''}
                    data-testid={`organization-row-${org.id}`}
                  >
                    <TableCell>
                      <div className="flex items-center space-x-2">
                        <Building className="h-4 w-4 text-gray-500" />
                        <div>
                          <div className="font-medium">{org.name}</div>
                          {org.description && (
                            <div className="text-xs text-muted-foreground">
                              {org.description}
                            </div>
                          )}
                        </div>
                      </div>
                    </TableCell>
                    <TableCell>
                      <Badge className={getPlanColor(org.plan)}>
                        {org.plan.toUpperCase()}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      <div className="text-sm">
                        {org.memberCount || 0} members
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="text-sm text-muted-foreground">
                        {new Date(org.createdAt).toLocaleDateString()}
                      </div>
                    </TableCell>
                    <TableCell>
                      <Badge variant="default" className="text-green-600 bg-green-50 border-green-200">
                        Active
                      </Badge>
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center space-x-2">
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => setSelectedOrganization(
                            selectedOrganization === org.id ? '' : org.id
                          )}
                          data-testid={`view-organization-${org.id}`}
                        >
                          <Users className="h-4 w-4 mr-1" />
                          {selectedOrganization === org.id ? 'Hide' : 'View'}
                        </Button>
                        <Button
                          variant="outline"
                          size="sm"
                          data-testid={`edit-organization-${org.id}`}
                        >
                          <Edit className="h-4 w-4" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          ) : (
            <div className="text-center py-8 text-muted-foreground">
              <Building className="h-12 w-12 mx-auto mb-4 opacity-50" />
              <p>No organizations found</p>
              <p className="text-sm">Create your first organization to get started</p>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Organization Members (when organization is selected) */}
      {selectedOrganization && members && (
        <Card data-testid="organization-members">
          <CardHeader>
            <CardTitle>Organization Members</CardTitle>
            <CardDescription>
              Members and their roles in the selected organization
            </CardDescription>
          </CardHeader>
          <CardContent>
            {members.members?.length > 0 ? (
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>User</TableHead>
                    <TableHead>Role</TableHead>
                    <TableHead>Joined</TableHead>
                    <TableHead>Last Active</TableHead>
                    <TableHead>Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {members.members.map((member: any) => (
                    <TableRow key={member.id} data-testid={`member-row-${member.id}`}>
                      <TableCell>
                        <div className="flex items-center space-x-2">
                          <div className="h-8 w-8 bg-gray-200 rounded-full flex items-center justify-center">
                            <Users className="h-4 w-4" />
                          </div>
                          <div>
                            <div className="font-medium">{member.user?.email || member.userId}</div>
                            <div className="text-xs text-muted-foreground">
                              {member.user?.firstName} {member.user?.lastName}
                            </div>
                          </div>
                        </div>
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center space-x-2">
                          {getRoleIcon(member.role)}
                          <Badge className={getRoleColor(member.role)}>
                            {member.role.replace('_', ' ').toUpperCase()}
                          </Badge>
                        </div>
                      </TableCell>
                      <TableCell>
                        <div className="text-sm text-muted-foreground">
                          {new Date(member.createdAt).toLocaleDateString()}
                        </div>
                      </TableCell>
                      <TableCell>
                        <div className="text-sm text-muted-foreground">
                          {member.user?.updatedAt ? 
                            new Date(member.user.updatedAt).toLocaleDateString() : 
                            'Never'
                          }
                        </div>
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center space-x-2">
                          <Button
                            variant="outline"
                            size="sm"
                            data-testid={`edit-member-${member.id}`}
                          >
                            <Edit className="h-4 w-4" />
                          </Button>
                          {member.role !== 'super_admin' && (
                            <Button
                              variant="outline"
                              size="sm"
                              className="text-red-600 hover:text-red-700"
                              data-testid={`remove-member-${member.id}`}
                            >
                              <Trash2 className="h-4 w-4" />
                            </Button>
                          )}
                        </div>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            ) : (
              <div className="text-center py-6 text-muted-foreground">
                <UserPlus className="h-8 w-8 mx-auto mb-2 opacity-50" />
                <p>No members found</p>
                <p className="text-sm">Invite users to join this organization</p>
              </div>
            )}
          </CardContent>
        </Card>
      )}
    </div>
  );
}

client/src/components/admin/PerformanceM.content:
import React, { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { 
  Zap, 
  Clock, 
  TrendingUp, 
  AlertTriangle,
  Activity,
  Server,
  BarChart3,
  RefreshCw
} from 'lucide-react';

interface PerformanceMonitoringProps {
  organizationId?: string;
  userRole: string;
}

export function PerformanceMonitoring({ organizationId, userRole }: PerformanceMonitoringProps) {
  const [timeRange, setTimeRange] = useState('1h');
  const [isRefreshing, setIsRefreshing] = useState(false);

  // Fetch performance analytics
  const { data: performanceData, isLoading, refetch } = useQuery({
    queryKey: ['/api/monitoring/performance', organizationId, timeRange],
    enabled: ['super_admin', 'admin', 'manager'].includes(userRole),
    refetchInterval: 30000, // 30 seconds
    throwOnError: false,
    retry: false
  });

  // Fetch error analytics
  const { data: errorData } = useQuery({
    queryKey: ['/api/monitoring/errors', organizationId, '24h'],
    enabled: ['super_admin', 'admin'].includes(userRole),
    throwOnError: false,
    retry: false
  });

  // Fetch real-time system metrics
  const { data: realtimeMetrics } = useQuery({
    queryKey: ['/api/monitoring/metrics/realtime', organizationId],
    enabled: ['super_admin', 'admin'].includes(userRole),
    refetchInterval: 10000, // 10 seconds
    throwOnError: false,
    retry: false
  });

  const handleManualRefresh = async () => {
    setIsRefreshing(true);
    await refetch();
    setTimeout(() => setIsRefreshing(false), 1000);
  };

  const getPerformanceColor = (value: number, thresholds: { good: number; warning: number }) => {
    if (value <= thresholds.good) return 'text-green-600';
    if (value <= thresholds.warning) return 'text-yellow-600';
    return 'text-red-600';
  };

  if (!['super_admin', 'admin', 'manager'].includes(userRole)) {
    return (
      <Card data-testid="performance-access-denied">
        <CardHeader>
          <CardTitle>Performance Monitoring</CardTitle>
          <CardDescription>Access denied - Management privileges required</CardDescription>
        </CardHeader>
      </Card>
    );
  }

  return (
    <div className="space-y-6" data-testid="performance-monitoring">
      {/* Header Controls */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-semibold">Performance Monitoring</h3>
          <p className="text-sm text-muted-foreground">
            Real-time system performance metrics and analytics
          </p>
        </div>
        <div className="flex items-center space-x-4">
          <Select value={timeRange} onValueChange={setTimeRange}>
            <SelectTrigger className="w-32" data-testid="time-range-select">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="1h">Last Hour</SelectItem>
              <SelectItem value="6h">Last 6 Hours</SelectItem>
              <SelectItem value="24h">Last 24 Hours</SelectItem>
              <SelectItem value="7d">Last 7 Days</SelectItem>
            </SelectContent>
          </Select>
          <Button
            variant="outline"
            size="sm"
            onClick={handleManualRefresh}
            disabled={isRefreshing}
            data-testid="refresh-performance"
          >
            <RefreshCw className={`h-4 w-4 ${isRefreshing ? 'animate-spin' : ''}`} />
          </Button>
        </div>
      </div>

      {/* Real-time Metrics Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card data-testid="metric-response-time">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium flex items-center">
              <Clock className="h-4 w-4 mr-2 text-blue-500" />
              Avg Response Time
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className={`text-2xl font-bold ${getPerformanceColor(
              realtimeMetrics?.metrics?.response_time_avg || 0, 
              { good: 200, warning: 500 }
            )}`}>
              {realtimeMetrics?.metrics?.response_time_avg || 0}ms
            </div>
            <p className="text-xs text-muted-foreground">
              P95: {realtimeMetrics?.metrics?.response_time_p95 || 0}ms
            </p>
          </CardContent>
        </Card>

        <Card data-testid="metric-throughput">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium flex items-center">
              <Activity className="h-4 w-4 mr-2 text-green-500" />
              Throughput
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">
              {performanceData?.summary?.totalRequests || 0}
            </div>
            <p className="text-xs text-muted-foreground">
              requests in {timeRange}
            </p>
          </CardContent>
        </Card>

        <Card data-testid="metric-error-rate">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium flex items-center">
              <AlertTriangle className="h-4 w-4 mr-2 text-red-500" />
              Error Rate
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className={`text-2xl font-bold ${getPerformanceColor(
              realtimeMetrics?.metrics?.error_rate || 0,
              { good: 1, warning: 5 }
            )}`}>
              {realtimeMetrics?.metrics?.error_rate || 0}
            </div>
            <p className="text-xs text-muted-foreground">
              errors per minute
            </p>
          </CardContent>
        </Card>

        <Card data-testid="metric-uptime">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium flex items-center">
              <Server className="h-4 w-4 mr-2 text-purple-500" />
              Uptime
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-green-600">
              {Math.floor((realtimeMetrics?.metrics?.uptime_seconds || 0) / 3600)}h
            </div>
            <p className="text-xs text-muted-foreground">
              continuous operation
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Performance Analytics Chart Area */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Response Time Trends */}
        <Card data-testid="response-time-trends">
          <CardHeader>
            <CardTitle>Response Time Trends</CardTitle>
            <CardDescription>
              Average response time over {timeRange}
            </CardDescription>
          </CardHeader>
          <CardContent>
            {isLoading ? (
              <div className="h-64 bg-gray-100 dark:bg-gray-800 rounded animate-pulse" />
            ) : performanceData?.trends?.responseTimeTrend ? (
              <div className="space-y-4">
                {/* Mock chart representation */}
                <div className="h-48 border rounded-lg p-4 bg-gradient-to-b from-blue-50 to-transparent dark:from-blue-900/20">
                  <div className="h-full flex items-end space-x-2">
                    {performanceData.trends.responseTimeTrend.slice(0, 12).map((point: any, index: number) => (
                      <div 
                        key={index}
                        className="flex-1 bg-blue-500 rounded-t"
                        style={{ height: `${Math.max(10, (point.value / 1000) * 100)}%` }}
                        title={`${new Date(point.timestamp).toLocaleTimeString()}: ${point.value}ms`}
                      />
                    ))}
                  </div>
                </div>
                <div className="text-sm text-muted-foreground text-center">
                  Response time trend over the last {timeRange}
                </div>
              </div>
            ) : (
              <div className="h-48 flex items-center justify-center text-muted-foreground">
                <div className="text-center">
                  <BarChart3 className="h-8 w-8 mx-auto mb-2 opacity-50" />
                  <p>No performance data available</p>
                </div>
              </div>
            )}
          </CardContent>
        </Card>

        {/* Slowest Endpoints */}
        <Card data-testid="slowest-endpoints">
          <CardHeader>
            <CardTitle>Slowest Endpoints</CardTitle>
            <CardDescription>
              Endpoints with highest average response times
            </CardDescription>
          </CardHeader>
          <CardContent>
            {performanceData?.summary?.slowestEndpoints?.length > 0 ? (
              <div className="space-y-3">
                {performanceData.summary.slowestEndpoints.map((endpoint: any, index: number) => (
                  <div 
                    key={index}
                    className="flex items-center justify-between p-3 border rounded-lg"
                    data-testid={`slow-endpoint-${index}`}
                  >
                    <div className="flex items-center space-x-3">
                      <div className={`w-2 h-8 rounded ${
                        endpoint.avgTime > 1000 ? 'bg-red-500' :
                        endpoint.avgTime > 500 ? 'bg-yellow-500' :
                        'bg-green-500'
                      }`} />
                      <div>
                        <div className="text-sm font-medium">{endpoint.endpoint}</div>
                        <div className="text-xs text-muted-foreground">
                          Avg: {endpoint.avgTime}ms
                        </div>
                      </div>
                    </div>
                    <Badge variant={endpoint.avgTime > 1000 ? "destructive" : 
                                  endpoint.avgTime > 500 ? "secondary" : "default"}>
                      {endpoint.avgTime}ms
                    </Badge>
                  </div>
                ))}
              </div>
            ) : (
              <div className="text-center py-8 text-muted-foreground">
                <Zap className="h-8 w-8 mx-auto mb-2 opacity-50" />
                <p>No endpoint data available</p>
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      {/* Error Analytics */}
      {['super_admin', 'admin'].includes(userRole) && errorData && (
        <Card data-testid="error-analytics">
          <CardHeader>
            <CardTitle>Error Analytics</CardTitle>
            <CardDescription>
              Error patterns and recent incidents
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Error Summary */}
              <div className="space-y-4">
                <div className="text-sm font-medium">Error Summary (24h)</div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="text-center p-3 bg-red-50 dark:bg-red-900/20 rounded-lg">
                    <div className="text-lg font-semibold text-red-600">
                      {errorData.summary?.totalErrors || 0}
                    </div>
                    <div className="text-xs text-muted-foreground">Total Errors</div>
                  </div>
                  <div className="text-center p-3 bg-orange-50 dark:bg-orange-900/20 rounded-lg">
                    <div className="text-lg font-semibold text-orange-600">
                      {errorData.summary?.criticalErrors || 0}
                    </div>
                    <div className="text-xs text-muted-foreground">Critical</div>
                  </div>
                </div>
              </div>

              {/* Top Error Types */}
              <div className="space-y-4">
                <div className="text-sm font-medium">Top Error Types</div>
                {errorData.errorTypes?.length > 0 ? (
                  <div className="space-y-2">
                    {errorData.errorTypes.slice(0, 5).map((errorType: any, index: number) => (
                      <div 
                        key={index}
                        className="flex items-center justify-between"
                        data-testid={`error-type-${index}`}
                      >
                        <span className="text-sm">{errorType.type}</span>
                        <div className="flex items-center space-x-2">
                          <span className="text-sm font-medium">{errorType.count}</span>
                          <Badge variant="outline" className="text-xs">
                            {errorType.percentage}%
                          </Badge>
                        </div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <p className="text-sm text-muted-foreground">No error data available</p>
                )}
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Performance Alerts */}
      {realtimeMetrics?.alerts?.length > 0 && (
        <Card data-testid="performance-alerts">
          <CardHeader>
            <CardTitle className="flex items-center">
              <AlertTriangle className="h-5 w-5 mr-2 text-yellow-500" />
              Performance Alerts
            </CardTitle>
            <CardDescription>
              Active performance issues requiring attention
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              {realtimeMetrics.alerts.map((alert: any, index: number) => (
                <div 
                  key={index}
                  className={`p-4 rounded-lg border ${
                    alert.severity === 'high' ? 'bg-red-50 border-red-200 dark:bg-red-900/20' :
                    'bg-yellow-50 border-yellow-200 dark:bg-yellow-900/20'
                  }`}
                  data-testid={`performance-alert-${index}`}
                >
                  <div className="flex items-start justify-between">
                    <div>
                      <div className="text-sm font-medium">{alert.type.replace('_', ' ')}</div>
                      <div className="text-sm text-muted-foreground">{alert.message}</div>
                      <div className="text-xs text-muted-foreground mt-1">
                        {new Date(alert.timestamp).toLocaleString()}
                      </div>
                    </div>
                    <Badge 
                      variant={alert.severity === 'high' ? 'destructive' : 'secondary'}
                    >
                      {alert.severity.toUpperCase()}
                    </Badge>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

