interface SSOProvider {
  id: string;
  name: string;
  provider: "saml" | "oauth2" | "oidc" | "ldap" | "azure_ad" | "google" | "okta" | "auth0";
  status: "active" | "inactive" | "error" | "testing";
  description: string;
  configuration: {
    // SAML specific
    entityId?: string;
    ssoUrl?: string;
    x509Certificate?: string;
    // OAuth2/OIDC specific
    clientId?: string;
    clientSecret?: string;
    authorizationUrl?: string;
    tokenUrl?: string;
    userInfoUrl?: string;
    // LDAP specific
    serverUrl?: string;
    baseDN?: string;
    bindDN?: string;
    searchFilter?: string;
    // Common settings
    redirectUrl?: string;
    scopes?: string[];
    attributeMapping?: Record<string, string>;
  };
  domainRestrictions: string[];
  userProvisioning: {
    enabled: boolean;
    defaultRole: string;
    autoCreate: boolean;
    autoUpdate: boolean;
  };
  securitySettings: {
    forceSSL: boolean;
    sessionTimeout: number;
    mfaRequired: boolean;
    ipWhitelist: string[];
  };
  createdAt: Date;
  lastSync: Date | null;
  userCount: number;
  loginCount: number;
  errorCount: number;
}

interface SSOIntegrationProps {
  providers?: SSOProvider[];
  onProviderCreate?: (provider: Omit<SSOProvider, "id" | "createdAt" | "lastSync" | "userCount" | "loginCount" | "errorCount">) => void;
