import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { 
  FileText, 
  Download, 
  Clock, 
  CheckCircle, 
  AlertCircle,
  FileDown,
  Eye,
  Settings,
  Sparkles,
  BarChart3,
  BookOpen,
  Users,
  Lightbulb,
  Target,
  Shield
} from "lucide-react";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import type { ReportRequest, ReportResponse } from "@shared/schema";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";

interface ReportGenerationSectionProps {
  sessionId?: string;
  sessionHasResults?: boolean;
  onReportGenerated?: (report: ReportResponse) => void;
}

const REPORT_TYPE_INFO = {
  executive: {
    title: "Executive Summary",
    description: "High-level overview with key findings and recommendations (2-3 pages)",
    icon: BarChart3,
    color: "text-blue-600",
    bgColor: "bg-blue-50 dark:bg-blue-950/20",
    estimatedTime: "1-2 min"
  },
  detailed: {
    title: "Detailed Analysis",
    description: "Comprehensive report with full analysis and supporting evidence (5-8 pages)",
    icon: BookOpen,
    color: "text-green-600",
    bgColor: "bg-green-50 dark:bg-green-950/20",
    estimatedTime: "2-3 min"
  },
  full: {
    title: "Complete Report",
    description: "Full report with transcripts, methodology, and technical details (10+ pages)",
    icon: FileText,
    color: "text-purple-600",
    bgColor: "bg-purple-50 dark:bg-purple-950/20",
    estimatedTime: "3-5 min"
  }
} as const;

const FORMAT_INFO = {
  markdown: {
    title: "Markdown",
    description: "Plain text with formatting",
    icon: FileText,
    extension: ".md"
  },
  html: {
    title: "HTML",
    description: "Web page format",
    icon: Eye,
    extension: ".html"
  },
  pdf: {
    title: "PDF",
    description: "Portable document format",
    icon: FileDown,
    extension: ".pdf"
  }
} as const;

export function ReportGenerationSection({ 
  sessionId, 
  sessionHasResults = false,
  onReportGenerated 
}: ReportGenerationSectionProps) {
  const [reportType, setReportType] = useState<"executive" | "detailed" | "full">("detailed");
  const [includeCitations, setIncludeCitations] = useState(true);
  const [includeExpertSummary, setIncludeExpertSummary] = useState(true);
  const [format, setFormat] = useState<"markdown" | "pdf" | "html">("markdown");
  const [generatedReport, setGeneratedReport] = useState<ReportResponse | null>(null);
  const [showPreview, setShowPreview] = useState(false);

  const { toast } = useToast();
  const queryClient = useQueryClient();

  const reportMutation = useMutation({
    mutationFn: async (): Promise<ReportResponse> => {
      if (!sessionId) throw new Error("No session available");

      const request: ReportRequest = {
        session_id: sessionId,
        report_type: reportType,
        include_citations: includeCitations,
        include_expert_summary: includeExpertSummary,
        format: format
      };

      const response = await apiRequest("POST", "/api/report", request);

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "Failed to generate report");
      }

      return response.json();
    },
    onSuccess: (report: ReportResponse) => {
      setGeneratedReport(report);
      onReportGenerated?.(report);
      toast({
        title: "Report Generated Successfully!",
        description: `Your ${reportType} report is ready for download.`,
      });
      // Invalidate sessions to refresh data
      queryClient.invalidateQueries({ queryKey: ["/api/sessions"] });
    },
    onError: (error: Error) => {
      toast({
        title: "Report Generation Failed",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  const handleGenerateReport = () => {
    if (!sessionHasResults) {
      toast({
        title: "Cannot Generate Report",
        description: "Complete a debate session first to generate a report.",
        variant: "destructive",
      });
      return;
    }

    reportMutation.mutate();
  };

  const handleDownloadReport = () => {
    if (!generatedReport) return;

    let content = "";
    const formatInfo = FORMAT_INFO[format];

    if (format === "markdown") {
      content = convertReportToMarkdown(generatedReport);
    } else if (format === "html") {
      content = convertReportToHTML(generatedReport);
    } else if (format === "pdf") {
      // For PDF, we'll use the HTML version and let the browser handle PDF conversion
      content = convertReportToHTML(generatedReport);
    }

    const blob = new Blob([content], { 
      type: format === "pdf" ? "text/html" : format === "html" ? "text/html" : "text/markdown" 
    });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `report-${reportType}-${new Date().toISOString().split('T')[0]}${formatInfo.extension}`;
    link.click();
    URL.revokeObjectURL(url);

    toast({ 
      description: `Report downloaded as ${formatInfo.title}!` 
    });
  };

  const convertReportToMarkdown = (report: ReportResponse): string => {
    try {
      let markdown = `# ${report?.title || 'Generated Report'}\n\n`;

      // Metadata with null guards
      const metadata = report?.metadata || {};
      markdown += `**Generated:** ${metadata.generated_at ? new Date(metadata.generated_at).toLocaleString() : new Date().toLocaleString()}\n`;
      markdown += `**Report Type:** ${report?.report_type ? report.report_type.charAt(0).toUpperCase() + report.report_type.slice(1) : 'Unknown'}\n`;
      if (metadata.total_analysis_time) {
        markdown += `**Analysis Time:** ${metadata.total_analysis_time}\n`;
      }
      markdown += `\n---\n\n`;

      // Executive Summary with null guard
      markdown += `## Executive Summary\n\n${report?.executive_summary || 'No executive summary available.'}\n\n`;

      // Debate Overview with comprehensive null guards
      const debateOverview = report?.debate_overview;
      if (debateOverview) {
        markdown += `## Debate Overview\n\n`;
        markdown += `**Original Question:** ${debateOverview.original_question || 'N/A'}\n\n`;
        markdown += `**Methodology:** ${debateOverview.methodology || 'N/A'}\n\n`;
        markdown += `**Participants:** ${debateOverview.participants?.length ? debateOverview.participants.join(", ") : 'N/A'}\n\n`;
        markdown += `**Rounds Conducted:** ${debateOverview.rounds_conducted || 'N/A'}\n\n`;
        markdown += `**Consensus Reached:** ${debateOverview.consensus_reached || 'N/A'}\n\n`;

        const keyDissents = debateOverview.key_dissents || [];
        if (keyDissents.length > 0) {
          markdown += `### Key Dissenting Views\n\n`;
          keyDissents.forEach((dissent, index) => {
            if (dissent && typeof dissent === 'object') {
              markdown += `${index + 1}. **${dissent.position || 'Unnamed dissent'}**\n`;
              if (dissent.reasoning) {
                markdown += `   ${dissent.reasoning}\n`;
              }
            } else if (typeof dissent === 'string') {
              markdown += `${index + 1}. **${dissent}**\n`;
            }
            markdown += `\n`;
          });
        }

        const unresolvedQuestions = debateOverview.unresolved_questions || [];
        if (unresolvedQuestions.length > 0) {
          markdown += `### Unresolved Questions\n\n`;
          unresolvedQuestions.forEach((question, index) => {
            markdown += `${index + 1}. ${question || 'Unnamed question'}\n`;
          });
          markdown += `\n`;
        }
      }

      // Brainstorming Outcomes with comprehensive null guards
      const brainstormingOutcomes = report?.brainstorming_outcomes;
      if (brainstormingOutcomes) {
        markdown += `## Brainstorming Outcomes\n\n`;

        const collaborativeSolutions = brainstormingOutcomes.collaborative_solutions || [];
        if (collaborativeSolutions.length > 0) {
          markdown += `### Collaborative Solutions\n\n`;
          collaborativeSolutions.forEach((solution, index) => {
            if (solution) {
              markdown += `${index + 1}. **${solution.title || 'Unnamed solution'}**\n`;
              markdown += `   ${solution.description || 'No description available'}\n`;
              markdown += `   - **Feasibility:** ${solution.feasibility || 'N/A'}\n`;
              markdown += `   - **Impact:** ${solution.impact || 'N/A'}\n`;
              if (solution.timeline) markdown += `   - **Timeline:** ${solution.timeline}\n`;
              if (solution.resources_required?.length) {
                markdown += `   - **Resources:** ${solution.resources_required.join(", ")}\n`;
              }
              markdown += `\n`;
            }
          });
        }

        const implementationPlan = brainstormingOutcomes.implementation_plan || [];
        if (implementationPlan.length > 0) {
          markdown += `### Implementation Plan\n\n`;
          implementationPlan.forEach((step) => {
            if (step) {
              markdown += `${step.step || 'N/A'}. **${step.title || 'Unnamed step'}**\n`;
              markdown += `   ${step.description || 'No description available'}\n`;
              if (step.owner) markdown += `   - **Owner:** ${step.owner}\n`;
              if (step.timeline) markdown += `   - **Timeline:** ${step.timeline}\n`;
              if (step.dependencies?.length) {
                markdown += `   - **Dependencies:** ${step.dependencies.join(", ")}\n`;
              }
              markdown += `\n`;
            }
          });
        }
      }

      // Expert Analysis with comprehensive null guards
      const expertAnalysis = report?.expert_analysis;
      if (expertAnalysis) {
        markdown += `## Expert Analysis\n\n`;

        const domainExperts = expertAnalysis.domain_experts_consulted || [];
        if (domainExperts.length > 0) {
          markdown += `### Domain Experts Consulted\n\n`;
          domainExperts.forEach((expert, index) => {
            if (expert) {
              markdown += `${index + 1}. **${expert.role || 'Unknown role'}** (${expert.expert_type || 'Unknown type'})\n`;
              markdown += `   - **Confidence Level:** ${expert.confidence_level || 'N/A'}\n`;
              const keyContributions = expert.key_contributions || [];
              if (keyContributions.length > 0) {
                markdown += `   - **Key Contributions:**\n`;
                keyContributions.forEach(contribution => {
                  markdown += `     - ${contribution || 'No contribution specified'}\n`;
                });
              }
              markdown += `\n`;
            }
          });
        }

        const aiAgents = expertAnalysis.ai_agents_summary || [];
        if (aiAgents.length > 0) {
          markdown += `### AI Agents Summary\n\n`;
          aiAgents.forEach((agent, index) => {
            if (agent) {
              markdown += `${index + 1}. **${agent.agent_name || 'Unnamed agent'}** - ${agent.role || 'Unknown role'}\n`;
              markdown += `   - **Approach:** ${agent.approach || 'N/A'}\n`;
              const keyInsights = agent.key_insights || [];
              if (keyInsights.length > 0) {
                markdown += `   - **Key Insights:**\n`;
                keyInsights.forEach(insight => {
                  markdown += `     - ${insight || 'No insight specified'}\n`;
                });
              }
              markdown += `\n`;
            }
          });
        }
      }

      // Recommendations with null guards
      const recommendations = report?.recommendations || [];
      if (recommendations.length > 0) {
        markdown += `## Recommendations\n\n`;
        recommendations.forEach((rec, index) => {
          if (rec) {
            markdown += `${index + 1}. **${rec.title || 'Unnamed recommendation'}** (Priority: ${rec.priority || 'N/A'})\n`;
            markdown += `   ${rec.description || 'No description available'}\n`;
            if (rec.timeline) markdown += `   - **Timeline:** ${rec.timeline}\n`;
            if (rec.stakeholders?.length) {
              markdown += `   - **Stakeholders:** ${rec.stakeholders.join(", ")}\n`;
            }
            markdown += `\n`;
          }
        });
      }

      // Citations with comprehensive null guards
      const citations = report?.citations || [];
      if (citations.length > 0) {
        markdown += `## Citations\n\n`;
        citations.forEach((citation, index) => {
          if (citation) {
            markdown += `${index + 1}. `;
            if (citation.title) markdown += `**${citation.title}**. `;
            if (citation.author) markdown += `${citation.author}. `;
            if (citation.year) markdown += `(${citation.year}). `;
            if (citation.source) markdown += `${citation.source}. `;
            if (citation.url) markdown += `[Link](${citation.url})`;
            if (citation.relevance) markdown += ` - ${citation.relevance}`;
            markdown += `\n`;
          }
        });
      }

      return markdown;
    } catch (error) {
      console.error('Error converting report to markdown:', error);
      // Return a safe fallback markdown
      return `# ${report?.title || 'Generated Report'}

## Error
An error occurred while formatting this report. Please try downloading in a different format.

**Report Type:** ${report?.report_type || 'Unknown'}
**Generated:** ${report?.metadata?.generated_at ? new Date(report.metadata.generated_at).toLocaleString() : new Date().toLocaleString()}

## Executive Summary
${report?.executive_summary || 'No summary available.'}
`;
    }
  };

  const convertReportToHTML = (report: ReportResponse): string => {
    // This is a simplified HTML conversion
    // In a production app, you might want to use a more sophisticated markdown-to-HTML converter
    const markdown = convertReportToMarkdown(report);

    let html = `
<!DOCTYPE html>
<html>
<head>
    <title>${report.title}</title>
    <style>
        body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; max-width: 800px; margin: 0 auto; padding: 20px; line-height: 1.6; }
        h1, h2, h3 { color: #2563eb; }
        h1 { border-bottom: 2px solid #e5e7eb; padding-bottom: 10px; }
        h2 { border-bottom: 1px solid #e5e7eb; padding-bottom: 5px; }
        blockquote { border-left: 4px solid #3b82f6; padding-left: 16px; margin: 16px 0; background: #f8fafc; }
        ul, ol { padding-left: 20px; }
        li { margin: 4px 0; }
        strong { color: #1e40af; }
        hr { border: none; border-top: 1px solid #e5e7eb; margin: 24px 0; }
    </style>
</head>
<body>
${markdown
  .replace(/^# (.+)$/gm, '<h1>$1</h1>')
  .replace(/^## (.+)$/gm, '<h2>$1</h2>')
  .replace(/^### (.+)$/gm, '<h3>$1</h3>')
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  .replace(/^---$/gm, '<hr>')
  .replace(/^\d+\. (.+)$/gm, '<li>$1</li>')
  .replace(/^- (.+)$/gm, '<li>$1</li>')
  .replace(/\n\n/g, '</p><p>')
  .replace(/^/, '<p>')
  .replace(/$/, '</p>')
}
</body>
</html>`;

    return html;
  };

  const previewReport = () => {
    if (generatedReport) {
      setShowPreview(true);
    }
  };

  if (!sessionHasResults) {
    return (
      <Card className="card-elevated">
        <CardHeader>
          <CardTitle className="flex items-center gap-3">
            <FileText className="text-muted-foreground" size={20} />
            Report Generation
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="text-center py-8" data-testid="no-results-state">
            <AlertCircle className="mx-auto mb-4 text-muted-foreground" size={48} />
            <h3 className="text-lg font-medium mb-2">No Results Available</h3>
            <p className="text-muted-foreground mb-4">
              Complete a debate session first to generate comprehensive reports.
            </p>
            <p className="text-sm text-muted-foreground">
              Start a debate session to unlock comprehensive report generation with AI-powered insights.
            </p>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6" data-testid="section-report-generation">
      {/* Configuration Card */}
      <Card className="card-elevated">
        <CardHeader>
          <CardTitle className="flex items-center gap-3">
            <FileText className="text-secondary" size={20} />
            Report Generation
            {generatedReport && (
              <Badge className="ml-auto" variant="secondary">
                <CheckCircle size={12} className="mr-1" />
                Ready
              </Badge>
            )}
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Report Type Selection */}
          <div className="space-y-4">
            <Label className="text-base font-medium">Report Type</Label>
            <RadioGroup 
              value={reportType} 
              onValueChange={(value: "executive" | "detailed" | "full") => setReportType(value)}
              className="space-y-3"
              data-testid="radiogroup-report-type"
            >
              {Object.entries(REPORT_TYPE_INFO).map(([type, info]) => {
                const IconComponent = info.icon;
                return (
                  <div key={type} className="flex items-start space-x-3">
                    <RadioGroupItem 
                      value={type} 
                      id={type} 
                      className="mt-1"
                      data-testid={`radio-report-type-${type}`}
                    />
                    <div className="flex-1">
                      <Label 
                        htmlFor={type} 
                        className="cursor-pointer"
                        data-testid={`label-report-type-${type}`}
                      >
                        <div className={`p-4 rounded-lg border-2 transition-all ${
                          reportType === type 
                            ? 'border-primary bg-primary/5' 
                            : 'border-border hover:border-primary/50'
                        }`}>
                          <div className="flex items-center gap-3 mb-2">
                            <IconComponent className={info.color} size={20} />
                            <span className="font-medium">{info.title}</span>
                            <Badge variant="outline" className="ml-auto">
                              <Clock size={12} className="mr-1" />
                              {info.estimatedTime}
                            </Badge>
                          </div>
                          <p className="text-sm text-muted-foreground">
                            {info.description}
                          </p>
                        </div>
                      </Label>
                    </div>
                  </div>
                );
              })}
            </RadioGroup>
          </div>

          <Separator />

          {/* Options */}
          <div className="space-y-4">
            <Label className="text-base font-medium">Report Options</Label>

            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <div className="space-y-1">
                  <Label 
                    htmlFor="include-citations"
                    className="text-sm font-medium"
                    data-testid="label-include-citations"
                  >
                    Include Citations
                  </Label>
                  <p className="text-xs text-muted-foreground">
                    Add source references and supporting evidence
                  </p>
                </div>
                <Switch
                  id="include-citations"
                  checked={includeCitations}
                  onCheckedChange={setIncludeCitations}
                  data-testid="switch-citations"
                />
              </div>

              <div className="flex items-center justify-between">
                <div className="space-y-1">
                  <Label 
                    htmlFor="include-expert-summary"
                    className="text-sm font-medium"
                    data-testid="label-include-expert-summary"
                  >
                    Include Expert Summary
                  </Label>
                  <p className="text-xs text-muted-foreground">
                    Add analysis from domain experts and AI agents
                  </p>
                </div>
                <Switch
                  id="include-expert-summary"
                  checked={includeExpertSummary}
                  onCheckedChange={setIncludeExpertSummary}
                  data-testid="switch-expert-summary"
                />
              </div>
            </div>
          </div>

          <Separator />

          {/* Format Selection */}
          <div className="space-y-4">
            <Label className="text-base font-medium">Output Format</Label>
            <RadioGroup 
              value={format} 
              onValueChange={(value: "markdown" | "pdf" | "html") => setFormat(value)}
              className="grid grid-cols-3 gap-4"
              data-testid="radiogroup-format"
            >
              {Object.entries(FORMAT_INFO).map(([formatType, info]) => {
                const IconComponent = info.icon;
                return (
                  <div key={formatType}>
                    <RadioGroupItem 
                      value={formatType} 
                      id={formatType} 
                      className="sr-only"
                      data-testid={`radio-format-${formatType}`}
                    />
                    <Label 
                      htmlFor={formatType} 
                      className="cursor-pointer"
                      data-testid={`label-format-${formatType}`}
                    >
                      <div className={`p-4 rounded-lg border-2 text-center transition-all ${
                        format === formatType 
                          ? 'border-primary bg-primary/5' 
                          : 'border-border hover:border-primary/50'
                      }`}>
                        <IconComponent className="mx-auto mb-2 text-muted-foreground" size={24} />
                        <div className="font-medium text-sm">{info.title}</div>
                        <div className="text-xs text-muted-foreground">{info.description}</div>
                      </div>
                    </Label>
                  </div>
                );
              })}
            </RadioGroup>
          </div>

          <Separator />

          {/* Action Buttons */}
          <div className="flex flex-col sm:flex-row gap-3">
            <Button
              onClick={handleGenerateReport}
              disabled={reportMutation.isPending || !sessionHasResults}
              className="flex-1"
              data-testid="button-generate-report"
            >
              {reportMutation.isPending ? (
                <>
                  <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2" />
                  Generating Report...
                </>
              ) : !sessionHasResults ? (
                <>
                  <AlertCircle className="mr-2" size={16} />
                  Complete Debate First
                </>
              ) : (
                <>
                  <Sparkles className="mr-2" size={16} />
                  Generate {REPORT_TYPE_INFO[reportType].title}
                </>
              )}
            </Button>

            {generatedReport && (
              <>
                <Button
                  variant="outline"
                  onClick={previewReport}
                  data-testid="button-preview-report"
                >
                  <Eye className="mr-2" size={16} />
                  Preview
                </Button>
                <Button
                  variant="outline"
                  onClick={handleDownloadReport}
                  data-testid={`button-download-${format}`}
                >
                  <Download className="mr-2" size={16} />
                  Download
                </Button>
              </>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Generated Report Summary Card */}
      {generatedReport && (
        <Card className="card-elevated">
          <CardHeader>
            <CardTitle className="flex items-center gap-3">
              <CheckCircle className="text-green-600" size={20} />
              Report Generated
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
                <div>
                  <Label className="text-muted-foreground">Type</Label>
                  <div className="font-medium capitalize" data-testid="text-generated-report-type">
                    {generatedReport.report_type}
                  </div>
                </div>
                <div>
                  <Label className="text-muted-foreground">Generated</Label>
                  <div className="font-medium" data-testid="text-generated-report-time">
                    {new Date(generatedReport.metadata.generated_at).toLocaleDateString()}
                  </div>
                </div>
                <div>
                  <Label className="text-muted-foreground">Analysis Time</Label>
                  <div className="font-medium" data-testid="text-generated-analysis-time">
                    {generatedReport.metadata.total_analysis_time}
                  </div>
                </div>
                <div>
                  <Label className="text-muted-foreground">Word Count</Label>
                  <div className="font-medium" data-testid="text-generated-word-count">
                    {generatedReport.metadata.word_count?.toLocaleString() || "N/A"}
                  </div>
                </div>
              </div>

              <div>
                <Label className="text-muted-foreground">Title</Label>
                <div className="font-medium" data-testid="text-generated-report-title">
                  {generatedReport.title}
                </div>
              </div>

              <div>
                <Label className="text-muted-foreground">Executive Summary (Preview)</Label>
                <div className="text-sm bg-muted/50 p-3 rounded-md" data-testid="text-generated-executive-summary">
                  {generatedReport.executive_summary?.length > 200 
                    ? `${generatedReport.executive_summary?.substring(0, 200)}...` 
                    : generatedReport.executive_summary || "No executive summary available"
                  }
                </div>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Report Preview Dialog */}
      <Dialog open={showPreview} onOpenChange={setShowPreview}>
        <DialogContent className="max-w-4xl max-h-[80vh]">
          <DialogHeader>
            <DialogTitle data-testid="dialog-title-report-preview">
              Report Preview: {generatedReport?.title}
            </DialogTitle>
            <DialogDescription>
              {FORMAT_INFO[format].title} format preview
            </DialogDescription>
          </DialogHeader>
          <ScrollArea className="h-[60vh] w-full pr-4">
            <div className="prose prose-sm max-w-none" data-testid="content-report-preview">
              {generatedReport && format === "markdown" && (
                <pre className="whitespace-pre-wrap text-sm">
                  {convertReportToMarkdown(generatedReport)}
                </pre>
              )}
              {generatedReport && format === "html" && (
                <div dangerouslySetInnerHTML={{ 
                  __html: convertReportToHTML(generatedReport) 
                }} />
              )}
              {generatedReport && format === "pdf" && (
                <div className="text-center py-8">
                  <FileDown className="mx-auto mb-4 text-muted-foreground" size={48} />
                  <p className="text-muted-foreground">
                    PDF format preview not available. Download to view the PDF.
                  </p>
                </div>
              )}
            </div>
          </ScrollArea>
        </DialogContent>
      </Dialog>
    </div>
  );
}

client/src/components/ReportHistorySecti.content:
import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Separator } from "@/components/ui/separator";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { 
  FileText, 
  Download, 
  Trash2, 
  Search, 
  Calendar, 
  Clock,
  Filter,
  Eye,
  MoreHorizontal,
  ExternalLink
} from "lucide-react";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle, AlertDialogTrigger } from "@/components/ui/alert-dialog";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import type { GeneratedReport } from "@shared/schema";

interface ReportHistorySectionProps {
  onViewReport?: (report: GeneratedReport) => void;
}

const REPORT_TYPE_INFO = {
  executive: {
    title: "Executive Summary",
    color: "text-blue-600",
    bgColor: "bg-blue-50 dark:bg-blue-950/20",
    icon: FileText
  },
  detailed: {
    title: "Detailed Analysis", 
    color: "text-green-600",
    bgColor: "bg-green-50 dark:bg-green-950/20",
    icon: FileText
  },
  full: {
    title: "Complete Report",
    color: "text-purple-600", 
    bgColor: "bg-purple-50 dark:bg-purple-950/20",
    icon: FileText
  }
} as const;

export function ReportHistorySection({ onViewReport }: ReportHistorySectionProps) {
  const [searchQuery, setSearchQuery] = useState("");
  const [filterType, setFilterType] = useState<string>("all");
  const [currentPage, setCurrentPage] = useState(1);
  const reportsPerPage = 6;

  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Fetch user's reports
  const { data: reports = [], isLoading, error } = useQuery({
    queryKey: ["/api/reports"],
    queryFn: async (): Promise<GeneratedReport[]> => {
      const response = await apiRequest("GET", "/api/reports");
      if (!response.ok) {
        throw new Error("Failed to fetch reports");
      }
      return response.json();
    },
  });

  // Delete report mutation
  const deleteMutation = useMutation({
    mutationFn: async (reportId: string): Promise<void> => {
      const response = await apiRequest("DELETE", `/api/reports/${reportId}`);
      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "Failed to delete report");
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/reports"] });
      toast({
        title: "Report Deleted",
        description: "The report has been successfully deleted.",
      });
    },
    onError: (error: Error) => {
      toast({
        title: "Delete Failed",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  // Filter and search reports
  const filteredReports = reports.filter(report => {
    const matchesSearch = !searchQuery || 
      report.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      (report.metadata as any)?.sessionPrompt?.toLowerCase().includes(searchQuery.toLowerCase());

    const matchesType = filterType === "all" || report.reportType === filterType;

    return matchesSearch && matchesType;
  });

  // Pagination
  const totalPages = Math.ceil(filteredReports.length / reportsPerPage);
  const startIndex = (currentPage - 1) * reportsPerPage;
  const paginatedReports = filteredReports.slice(startIndex, startIndex + reportsPerPage);

  const handleDeleteReport = (reportId: string) => {
    deleteMutation.mutate(reportId);
  };

  const handleDownloadReport = async (report: GeneratedReport) => {
    try {
      let content = report.content;
      let mimeType = "text/plain";
      let extension = ".txt";

      if (report.format === "html") {
        mimeType = "text/html";
        extension = ".html";
      } else if (report.format === "markdown") {
        mimeType = "text/markdown";
        extension = ".md";
      } else {
        // JSON format
        mimeType = "application/json";
        extension = ".json";
      }

      const defaultFileName = `${report.title.replace(/[^a-z0-9]/gi, '_')}${extension}`;

      // Use File System Access API if available (Chrome, Edge, etc.)
      if ('showSaveFilePicker' in window) {
        try {
          const fileHandle = await (window as any).showSaveFilePicker({
            suggestedName: defaultFileName,
            types: [{
              description: `${report.format.toUpperCase()} files`,
              accept: {
                [mimeType]: [extension],
              },
            }],
          });

          const writable = await fileHandle.createWritable();
          await writable.write(content);
          await writable.close();

          toast({
            description: "Report saved successfully to chosen location!",
          });
        } catch (saveError: any) {
          // User cancelled or error occurred, fall back to default download
          if (saveError.name !== 'AbortError') {
            throw saveError;
          }
        }
      } else {
        // Fallback to traditional download for browsers that don't support File System Access API
        const blob = new Blob([content], { type: mimeType });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = defaultFileName;
        link.click();
        URL.revokeObjectURL(url);

        toast({
          description: "Report downloaded successfully!",
        });
      }
    } catch (error) {
      toast({
        title: "Download Failed",
        description: "Failed to download the report.",
        variant: "destructive",
      });
    }
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  if (isLoading) {
    return (
      <Card className="card-elevated h-full">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <FileText className="h-5 w-5" />
            Report History
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-center justify-center py-8">
            <div className="text-center space-y-2">
              <div className="h-8 w-8 border-2 border-primary border-t-transparent rounded-full animate-spin mx-auto"></div>
              <p className="text-sm text-muted-foreground">Loading reports...</p>
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (error) {
    return (
      <Card className="card-elevated h-full">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <FileText className="h-5 w-5" />
            Report History
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="text-center py-8">
            <p className="text-sm text-destructive">Failed to load reports</p>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="card-elevated h-full">
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <FileText className="h-5 w-5" />
          Report History
          {reports.length > 0 && (
            <Badge variant="secondary" data-testid="text-report-count">
              {reports.length}
            </Badge>
          )}
        </CardTitle>

        {/* Search and Filter Controls */}
        <div className="flex flex-col sm:flex-row gap-4">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Search reports..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-9"
              data-testid="input-search-reports"
            />
          </div>
          <div className="flex items-center gap-2">
            <Filter className="h-4 w-4 text-muted-foreground" />
            <Select value={filterType} onValueChange={setFilterType}>
              <SelectTrigger className="w-[150px]" data-testid="select-filter-type">
                <SelectValue placeholder="Filter by type" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Types</SelectItem>
                <SelectItem value="executive">Executive</SelectItem>
                <SelectItem value="detailed">Detailed</SelectItem>
                <SelectItem value="full">Complete</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </div>
      </CardHeader>

      <CardContent>
        {filteredReports.length === 0 ? (
          <div className="text-center py-8">
            <FileText className="h-12 w-12 text-muted-foreground/50 mx-auto mb-4" />
            <h3 className="text-lg font-medium mb-2">
              {reports.length === 0 ? "No Reports Yet" : "No Matching Reports"}
            </h3>
            <p className="text-sm text-muted-foreground">
              {reports.length === 0 
                ? "Generate your first report to see it here."
                : "Try adjusting your search or filter criteria."
              }
            </p>
          </div>
        ) : (
          <div className="space-y-4">
            <ScrollArea className="h-[400px]">
              <div className="grid gap-4">
                {paginatedReports.map((report) => {
                  const typeInfo = REPORT_TYPE_INFO[report.reportType as keyof typeof REPORT_TYPE_INFO];
                  const Icon = typeInfo?.icon || FileText;

                  return (
                    <Card key={report.id} className="hover:bg-accent/50 transition-colors" data-testid={`card-report-${report.id}`}>
                      <CardContent className="p-4">
                        <div className="flex items-start justify-between">
                          <div className="flex-1 space-y-2">
                            <div className="flex items-center gap-2">
                              <Icon className={`h-4 w-4 ${typeInfo?.color || 'text-gray-600'}`} />
                              <Badge 
                                variant="secondary" 
                                className={typeInfo?.bgColor || 'bg-gray-50'}
                                data-testid={`badge-type-${report.reportType}`}
                              >
                                {typeInfo?.title || report.reportType}
                              </Badge>
                              <Badge variant="outline" data-testid={`badge-format-${report.format}`}>
                                {report.format.toUpperCase()}
                              </Badge>
                            </div>

                            <h4 
                              className="font-medium line-clamp-2 cursor-pointer hover:text-primary"
                              onClick={() => onViewReport?.(report)}
                              data-testid={`text-report-title`}
                            >
                              {report.title}
                            </h4>

                            <div className="flex items-center gap-4 text-xs text-muted-foreground">
                              <div className="flex items-center gap-1">
                                <Calendar className="h-3 w-3" />
                                <span data-testid="text-generated-date">
                                  {report.generatedAt ? formatDate(typeof report.generatedAt === 'string' ? report.generatedAt : report.generatedAt.toString()) : 'Unknown'}
                                </span>
                              </div>
                              {(report.metadata as any)?.wordCount && (
                                <div className="flex items-center gap-1">
                                  <Clock className="h-3 w-3" />
                                  <span data-testid="text-word-count">
                                    {(report.metadata as any).wordCount} words
                                  </span>
                                </div>
                              )}
                            </div>

                            {(report.metadata as any)?.sessionPrompt && (
                              <p className="text-xs text-muted-foreground line-clamp-1" data-testid="text-session-prompt">
                                Session: {(report.metadata as any).sessionPrompt}
                              </p>
                            )}
                          </div>

                          <DropdownMenu>
                            <DropdownMenuTrigger asChild>
                              <Button variant="ghost" size="sm" data-testid="button-report-actions">
                                <MoreHorizontal className="h-4 w-4" />
                              </Button>
                            </DropdownMenuTrigger>
                            <DropdownMenuContent align="end">
                              <DropdownMenuItem onClick={() => onViewReport?.(report)} data-testid="action-view-report">
                                <Eye className="h-4 w-4 mr-2" />
                                View Report
                              </DropdownMenuItem>
                              <DropdownMenuItem onClick={() => handleDownloadReport(report)} data-testid="action-download-report">
                                <Download className="h-4 w-4 mr-2" />
                                Download
                              </DropdownMenuItem>
                              <Separator />
                              <AlertDialog>
                                <AlertDialogTrigger asChild>
                                  <DropdownMenuItem 
                                    onSelect={(e) => e.preventDefault()}
                                    className="text-destructive focus:text-destructive"
                                    data-testid="action-delete-report"
                                  >
                                    <Trash2 className="h-4 w-4 mr-2" />
                                    Delete
                                  </DropdownMenuItem>
                                </AlertDialogTrigger>
                                <AlertDialogContent>
                                  <AlertDialogHeader>
                                    <AlertDialogTitle>Delete Report</AlertDialogTitle>
                                    <AlertDialogDescription>
                                      Are you sure you want to delete "{report.title}"? This action cannot be undone.
                                    </AlertDialogDescription>
                                  </AlertDialogHeader>
                                  <AlertDialogFooter>
                                    <AlertDialogCancel data-testid="button-cancel-delete">Cancel</AlertDialogCancel>
                                    <AlertDialogAction 
                                      onClick={() => handleDeleteReport(report.id)}
                                      className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                                      data-testid="button-confirm-delete"
                                    >
                                      Delete
                                    </AlertDialogAction>
                                  </AlertDialogFooter>
                                </AlertDialogContent>
                              </AlertDialog>
                            </DropdownMenuContent>
                          </DropdownMenu>
                        </div>
                      </CardContent>
                    </Card>
                  );
                })}
              </div>
            </ScrollArea>

            {/* Pagination */}
            {totalPages > 1 && (
              <div className="flex items-center justify-between pt-4">
                <p className="text-sm text-muted-foreground">
                  Showing {startIndex + 1} to {Math.min(startIndex + reportsPerPage, filteredReports.length)} of {filteredReports.length} reports
                </p>
                <div className="flex items-center gap-2">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))}
                    disabled={currentPage === 1}
                    data-testid="button-prev-page"
                  >
                    Previous
                  </Button>
                  <span className="text-sm font-medium" data-testid="text-page-info">
                    Page {currentPage} of {totalPages}
                  </span>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))}
                    disabled={currentPage === totalPages}
                    data-testid="button-next-page"
                  >
                    Next
                  </Button>
                </div>
              </div>
            )}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

client/src/components/ReportViewerDialog.content:
import { useState } from "react";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Separator } from "@/components/ui/separator";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { 
  Download, 
  Printer, 
  FileText, 
  Clock, 
  Calendar,
  User,
  BarChart3,
  BookOpen,
  ExternalLink,
  Copy,
  X,
  ChevronDown
} from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";
import type { GeneratedReport } from "@shared/schema";

interface ReportViewerDialogProps {
  report: GeneratedReport | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

const REPORT_TYPE_INFO = {
  executive: {
    title: "Executive Summary",
    description: "High-level overview with key findings",
    icon: BarChart3,
    color: "text-blue-600",
    bgColor: "bg-blue-50 dark:bg-blue-950/20",
  },
  detailed: {
    title: "Detailed Analysis",
    description: "Comprehensive report with analysis",
    icon: BookOpen,
    color: "text-green-600",
    bgColor: "bg-green-50 dark:bg-green-950/20",
  },
  full: {
    title: "Complete Report",
    description: "Full report with all details",
    icon: FileText,
    color: "text-purple-600",
    bgColor: "bg-purple-50 dark:bg-purple-950/20",
  }
} as const;

const EXPORT_FORMATS = {
  local: {
    label: "Original Format",
    description: "Download in the report's current format",
    icon: FileText,
  },
  word: {
    label: "Word Document",
    description: "Download as Word (.docx) file",
    icon: FileText,
  },
  text: {
    label: "Plain Text",
    description: "Download as text (.txt) file",
    icon: FileText,
  },
  json: {
    label: "JSON Data",
    description: "Download as JSON (.json) file",
    icon: FileText,
  },
} as const;

export function ReportViewerDialog({ report, open, onOpenChange }: ReportViewerDialogProps) {
  const [isDownloading, setIsDownloading] = useState(false);
  const [selectedFormat, setSelectedFormat] = useState<string>("local");
  const { toast } = useToast();

  if (!report) return null;

  const typeInfo = REPORT_TYPE_INFO[report.reportType as keyof typeof REPORT_TYPE_INFO] || REPORT_TYPE_INFO.detailed;
  const IconComponent = typeInfo.icon;

  const handleWordDownload = async () => {
    setIsDownloading(true);

    try {
      // Call the backend API to generate Word document
      const response = await apiRequest('POST', '/api/export', {
        filename: `${report.title.replace(/[^a-z0-9]/gi, '_')}.docx`,
        content: report.content,
        format: 'docx',
        title: report.title,
        metadata: {
          reportType: report.reportType,
          generatedAt: report.generatedAt,
          sessionId: (report.metadata as any)?.sessionId,
          ...(report.metadata && typeof report.metadata === 'object' ? report.metadata : {})
        }
      });

      // Get the binary data from response
      const blob = await response.blob();

      // Create download link
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `${report.title.replace(/[^a-z0-9]/gi, '_')}.docx`;
      link.click();
      URL.revokeObjectURL(url);

      toast({
        description: "Word document downloaded successfully!",
      });
    } catch (error) {
      console.error('Word download failed:', error);
      toast({
        title: "Download Failed",
        description: "Failed to download Word document. Please try again.",
        variant: "destructive",
      });
    } finally {
      setIsDownloading(false);
    }
  };

  const handleLocalDownload = async (format: string) => {
    setIsDownloading(true);

    try {
      let content = report.content;
      let mimeType = "text/plain";
      let extension = ".txt";
      let formatLabel = "text";

      if (format === "json") {
        // Create JSON format
        const jsonData = {
          title: report.title,
          reportType: report.reportType,
          format: report.format,
          content: report.content,
          metadata: report.metadata,
          generatedAt: report.generatedAt
        };
        content = JSON.stringify(jsonData, null, 2);
        mimeType = "application/json";
        extension = ".json";
        formatLabel = "JSON";
      } else if (format === "text") {
        // Plain text format
        content = report.content;
        mimeType = "text/plain";
        extension = ".txt";
        formatLabel = "text";
      } else {
        // Original format
        if (report.format === "html") {
          mimeType = "text/html";
          extension = ".html";
          formatLabel = "HTML";
        } else if (report.format === "markdown") {
          mimeType = "text/markdown";
          extension = ".md";
          formatLabel = "Markdown";
        } else {
          mimeType = "text/plain";
          extension = ".txt";
          formatLabel = "text";
        }
      }

      const defaultFileName = `${report.title.replace(/[^a-z0-9]/gi, '_')}${extension}`;

      // Use File System Access API if available (Chrome, Edge, etc.)
      if ('showSaveFilePicker' in window) {
        try {
          const fileHandle = await (window as any).showSaveFilePicker({
            suggestedName: defaultFileName,
            types: [{
              description: `${formatLabel.toUpperCase()} files`,
              accept: {
                [mimeType]: [extension],
              },
            }],
          });

          const writable = await fileHandle.createWritable();
          await writable.write(content);
          await writable.close();

          toast({
            description: "Report saved successfully to chosen location!",
          });
        } catch (saveError: any) {
          // User cancelled or error occurred, fall back to default download
          if (saveError.name !== 'AbortError') {
            throw saveError;
          }
        }
      } else {
        // Fallback to traditional download for browsers that don't support File System Access API
        const blob = new Blob([content], { type: mimeType });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = defaultFileName;
        link.click();
        URL.revokeObjectURL(url);

        toast({
          description: "Report downloaded successfully!",
        });
      }
    } catch (error) {
      toast({
        title: "Download Failed",
        description: "Failed to download the report.",
        variant: "destructive",
      });
    } finally {
      setIsDownloading(false);
    }
  };

  const handleDownload = async () => {
    if (selectedFormat === "word") {
      await handleWordDownload();
    } else {
      await handleLocalDownload(selectedFormat);
    }
  };

  const handlePrint = () => {
    const printWindow = window.open('', '_blank');
    if (printWindow) {
      let printContent = report.content;

      // If it's markdown, convert basic formatting for printing
      if (report.format === "markdown") {
        printContent = convertMarkdownToHTML(printContent);
      }

      printWindow.document.write(`
        <!DOCTYPE html>
        <html>
        <head>
          <title>${report.title}</title>
          <style>
            body { 
              font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
              line-height: 1.6;
              color: #333;
              max-width: 800px;
              margin: 0 auto;
              padding: 20px;
            }
            h1, h2, h3, h4, h5, h6 { color: #2d3748; margin-top: 24px; margin-bottom: 16px; }
            h1 { font-size: 2em; border-bottom: 2px solid #e2e8f0; padding-bottom: 8px; }
            h2 { font-size: 1.5em; border-bottom: 1px solid #e2e8f0; padding-bottom: 4px; }
            p { margin-bottom: 16px; }
            ul, ol { margin-bottom: 16px; padding-left: 24px; }
            li { margin-bottom: 4px; }
            blockquote { 
              border-left: 4px solid #4299e1; 
              padding-left: 16px; 
              margin: 16px 0; 
              color: #718096; 
            }
            code { 
              background-color: #f7fafc; 
              padding: 2px 4px; 
              border-radius: 3px; 
              font-family: 'Monaco', 'Menlo', monospace;
            }
            pre { 
              background-color: #f7fafc; 
              padding: 16px; 
              border-radius: 6px; 
              overflow-x: auto;
              font-family: 'Monaco', 'Menlo', monospace;
            }
            .report-header {
              text-align: center;
              border-bottom: 2px solid #e2e8f0;
              padding-bottom: 20px;
              margin-bottom: 30px;
            }
            .report-meta {
              font-size: 0.9em;
              color: #718096;
              margin-top: 10px;
            }
          </style>
        </head>
        <body>
          <div class="report-header">
            <h1>${report.title}</h1>
            <div class="report-meta">
              <p>Report Type: ${typeInfo.title}</p>
              <p>Generated: ${report.generatedAt ? new Date(report.generatedAt).toLocaleString() : 'Unknown'}</p>
              <p>Format: ${report.format.toUpperCase()}</p>
            </div>
          </div>
          ${report.format === "html" ? printContent : `<pre>${printContent}</pre>`}
        </body>
        </html>
      `);
      printWindow.document.close();
      printWindow.print();
    }
  };

  const handleCopyContent = async () => {
    try {
      await navigator.clipboard.writeText(report.content);
      toast({
        description: "Report content copied to clipboard!",
      });
    } catch (error) {
      toast({
        title: "Copy Failed",
        description: "Failed to copy report content.",
        variant: "destructive",
      });
    }
  };

  const convertMarkdownToHTML = (markdown: string): string => {
    // Basic markdown to HTML conversion for printing
    return markdown
      // Headers
      .replace(/^# (.*$)/gm, '<h1>$1</h1>')
      .replace(/^## (.*$)/gm, '<h2>$1</h2>')
      .replace(/^### (.*$)/gm, '<h3>$1</h3>')
      .replace(/^#### (.*$)/gm, '<h4>$1</h4>')
      // Bold and italic
      .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
      .replace(/\*(.*?)\*/g, '<em>$1</em>')
      // Links
      .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank">$1</a>')
      // Line breaks
      .replace(/\n\n/g, '</p><p>')
      .replace(/^\s*/, '<p>')
      .replace(/\s*$/, '</p>')
      // Lists (basic)
      .replace(/^\* (.*$)/gm, '<li>$1</li>')
      .replace(/(<li>.*<\/li>)/g, '<ul>$1</ul>');
  };

  const formatDate = (date: Date | null | string) => {
    if (!date) return 'Unknown';
    const dateObj = typeof date === 'string' ? new Date(date) : date;
    return dateObj.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const getContentPreview = (content: string, maxLength: number = 200) => {
    if (content.length <= maxLength) return content;
    return content.substring(0, maxLength) + '...';
  };

  const renderContent = () => {
    if (report.format === "html") {
      return (
        <div 
          className="prose prose-sm max-w-none dark:prose-invert"
          dangerouslySetInnerHTML={{ __html: report.content }}
          data-testid="report-html-content"
        />
      );
    } else {
      // For markdown and other formats, display as preformatted text
      return (
        <div className="font-mono text-sm whitespace-pre-wrap" data-testid="report-text-content">
          {report.content}
        </div>
      );
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-4xl max-h-[90vh] flex flex-col">
        <DialogHeader>
          <div className="flex items-start justify-between">
            <div className="flex-1">
              <DialogTitle className="text-xl font-semibold pr-8" data-testid="report-viewer-title">
                {report.title}
              </DialogTitle>
              <DialogDescription className="mt-2">
                <div className="flex items-center gap-4 flex-wrap">
                  <div className="flex items-center gap-2">
                    <IconComponent className={`h-4 w-4 ${typeInfo.color}`} />
                    <Badge 
                      variant="secondary" 
                      className={`${typeInfo.bgColor} ${typeInfo.color} font-medium`}
                      data-testid="report-type-badge"
                    >
                      {typeInfo.title}
                    </Badge>
                  </div>
                  <div className="flex items-center gap-2">
                    <Calendar className="h-4 w-4 text-muted-foreground" />
                    <span className="text-sm text-muted-foreground" data-testid="report-date">
                      {formatDate(report.generatedAt)}
                    </span>
                  </div>
                  <div className="flex items-center gap-2">
                    <FileText className="h-4 w-4 text-muted-foreground" />
                    <span className="text-sm text-muted-foreground" data-testid="report-format">
                      {report.format.toUpperCase()}
                    </span>
                  </div>
                </div>
              </DialogDescription>
            </div>
          </div>
        </DialogHeader>

        <Separator />

        {/* Action Buttons */}
        <div className="flex items-center gap-2 py-2">
          <div className="flex items-center gap-2">
            <Select value={selectedFormat} onValueChange={setSelectedFormat}>
              <SelectTrigger className="w-48" data-testid="select-export-format">
                <SelectValue placeholder="Choose format" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="local">
                  <div className="flex items-center gap-2">
                    <FileText className="h-4 w-4" />
                    <div>
                      <div className="font-medium">{EXPORT_FORMATS.local.label}</div>
                      <div className="text-xs text-muted-foreground">{EXPORT_FORMATS.local.description}</div>
                    </div>
                  </div>
                </SelectItem>
                <SelectItem value="word">
                  <div className="flex items-center gap-2">
                    <FileText className="h-4 w-4" />
                    <div>
                      <div className="font-medium">{EXPORT_FORMATS.word.label}</div>
                      <div className="text-xs text-muted-foreground">{EXPORT_FORMATS.word.description}</div>
                    </div>
                  </div>
                </SelectItem>
                <SelectItem value="text">
                  <div className="flex items-center gap-2">
                    <FileText className="h-4 w-4" />
                    <div>
                      <div className="font-medium">{EXPORT_FORMATS.text.label}</div>
                      <div className="text-xs text-muted-foreground">{EXPORT_FORMATS.text.description}</div>
                    </div>
                  </div>
                </SelectItem>
                <SelectItem value="json">
                  <div className="flex items-center gap-2">
                    <FileText className="h-4 w-4" />
                    <div>
                      <div className="font-medium">{EXPORT_FORMATS.json.label}</div>
                      <div className="text-xs text-muted-foreground">{EXPORT_FORMATS.json.description}</div>
                    </div>
                  </div>
                </SelectItem>
              </SelectContent>
            </Select>

            <Button
              variant="outline"
              size="sm"
              onClick={handleDownload}
              disabled={isDownloading}
              data-testid="button-download-report"
            >
              <Download className="h-4 w-4 mr-2" />
              {isDownloading ? "Downloading..." : "Download"}
            </Button>
          </div>
          <Button
            variant="outline"
            size="sm"
            onClick={handlePrint}
            data-testid="button-print-report"
          >
            <Printer className="h-4 w-4 mr-2" />
            Print
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={handleCopyContent}
            data-testid="button-copy-report"
          >
            <Copy className="h-4 w-4 mr-2" />
            Copy Text
          </Button>

          {/* Session Info */}
          {(report.metadata as any)?.sessionId && (
            <div className="flex items-center gap-2 ml-auto">
              <User className="h-4 w-4 text-muted-foreground" />
              <span className="text-xs text-muted-foreground" data-testid="report-session-info">
                Session: {((report.metadata as any)?.sessionId as string).substring(0, 8)}...
              </span>
            </div>
          )}
        </div>

        <Separator />

        {/* Report Content */}
        <div className="flex-1 min-h-0">
          <ScrollArea className="h-full">
            <div className="p-4">
              {renderContent()}
            </div>
          </ScrollArea>
        </div>

        {/* Footer with metadata */}
        <div className="border-t pt-4 mt-4">
          <div className="grid grid-cols-2 gap-4 text-sm text-muted-foreground">
            <div>
              <div className="font-medium text-foreground mb-1">Report Details</div>
              <div className="space-y-1">
                <div>Type: {typeInfo.title}</div>
                <div>Format: {report.format.toUpperCase()}</div>
