            config.color === 'blue' ? 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200' :
            config.color === 'purple' ? 'bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-200' :
            config.color === 'emerald' ? 'bg-emerald-100 text-emerald-800 dark:bg-emerald-900 dark:text-emerald-200' :
            'bg-gray-100 text-gray-800 dark:bg-gray-900 dark:text-gray-200'
          }>
            Transfer Available
          </Badge>
        </div>
      </CardHeader>

      <CardContent className="space-y-4">
        {/* Transfer Reason */}
        {reason && (
          <div className="p-3 bg-white dark:bg-gray-800 rounded-lg border border-gray-200 dark:border-gray-700">
            <div className="flex items-center gap-2 mb-1">
              <reason.icon size={16} className="text-orange-500" />
              <span className="font-medium text-sm text-gray-900 dark:text-gray-100">
                {reason.title}
              </span>
            </div>
            <p className="text-xs text-gray-600 dark:text-gray-400">
              {context?.customReason || reason.description}
            </p>
          </div>
        )}

        {/* Current Session Context */}
        {context?.sessionData && (
          <div className="space-y-2">
            <div className="text-sm font-medium text-blue-800 dark:text-blue-200">
              Current Analysis Status:
            </div>

            {context.sessionData.consensus && (
              <div className="text-xs text-gray-600 dark:text-gray-400 bg-white dark:bg-gray-800 p-2 rounded border-l-2 border-green-400">
                <span className="font-medium">Consensus: </span>
                {context.sessionData.consensus.substring(0, 100)}...
              </div>
            )}

            <div className="flex gap-4 text-xs">
              {context.sessionData.dissents && context.sessionData.dissents.length > 0 && (
                <div className="flex items-center gap-1 text-orange-600 dark:text-orange-400">
                  <span className="w-2 h-2 bg-orange-400 rounded-full"></span>
                  {context.sessionData.dissents.length} dissenting views
                </div>
              )}

              {context.sessionData.unresolved && context.sessionData.unresolved.length > 0 && (
                <div className="flex items-center gap-1 text-red-600 dark:text-red-400">
                  <span className="w-2 h-2 bg-red-400 rounded-full"></span>
                  {context.sessionData.unresolved.length} unresolved questions
                </div>
              )}

              {context.sessionData.quality && (
                <div className="flex items-center gap-1 text-blue-600 dark:text-blue-400">
                  <span className="w-2 h-2 bg-blue-400 rounded-full"></span>
                  {Math.round(context.sessionData.quality)}% confidence
                </div>
              )}
            </div>
          </div>
        )}

        {/* Benefits List */}
        <div className="space-y-3">
          <div className="text-sm font-medium text-blue-800 dark:text-blue-200">
            Enhanced Capabilities:
          </div>

          <ul className="space-y-2 text-sm">
            {config.benefits.map((benefit, index) => (
              <li key={index} className="flex items-start gap-2 text-blue-800 dark:text-blue-200">
                <ArrowRight size={14} className="text-blue-500 mt-0.5 flex-shrink-0" />
                <span>{benefit}</span>
              </li>
            ))}
          </ul>
        </div>

        {/* Performance Metrics */}
        {showMetrics && config.metrics && (
          <div className="p-3 bg-white dark:bg-gray-800 rounded-lg space-y-2">
            <div className="text-sm font-medium text-gray-900 dark:text-gray-100 flex items-center gap-2">
              <Shield size={16} />
              Expected Performance Impact:
            </div>

            <div className="grid grid-cols-3 gap-4 text-xs">
              <div className="text-center">
                <div className="font-medium text-green-600 dark:text-green-400">
                  +{config.metrics.qualityBoost}
                </div>
                <div className="text-gray-600 dark:text-gray-400">Quality</div>
              </div>

              <div className="text-center">
                <div className="font-medium text-orange-600 dark:text-orange-400">
                  {config.metrics.timeIncrease}
                </div>
                <div className="text-gray-600 dark:text-gray-400">Time</div>
              </div>

              <div className="text-center">
                <div className="font-medium text-blue-600 dark:text-blue-400">
                  {config.metrics.agents}
                </div>
                <div className="text-gray-600 dark:text-gray-400">Agents</div>
              </div>
            </div>
          </div>
        )}

        {/* Guidance Tip */}
        <div className="p-3 bg-gradient-to-r from-blue-100 to-purple-100 dark:from-blue-900 dark:to-purple-900 rounded-lg">
          <p className="text-xs text-blue-700 dark:text-blue-300 font-medium">
            💡 <strong>Pro Tip:</strong> {
              context?.toMode === 'guided' 
                ? 'Guided mode provides structured analysis with clear step-by-step reasoning.'
                : context?.toMode === 'expert'
                  ? 'Expert mode offers the deepest analysis with comprehensive audit trails and enterprise-grade insights.'
                  : 'Each mode builds upon the previous, carrying forward all context and insights while adding enhanced capabilities.'
            }
          </p>
        </div>
      </CardContent>
    </Card>
  );
}

client/src/hooks/useSSE.ts.content:
import { useEffect, useRef, useState, useCallback } from 'react';

interface SSEOptions {
  reconnectAttempts?: number;
  reconnectDelay?: number;
  timeout?: number;
  onEvent?: (event: string, data: any) => void;
  onError?: (error: Event) => void;
  onReconnect?: (attempt: number) => void;
}

interface SSEState {
  progress: number;
  status: 'idle' | 'connecting' | 'running' | 'completed' | 'failed' | 'reconnecting';
  data: any;
  error: string | null;
  reconnectAttempt: number;
  isConnected: boolean;
}

export function useSSE(url: string, options: SSEOptions = {}) {
  const {
    reconnectAttempts = 3,
    reconnectDelay = 2000,
    timeout = 30000,
    onEvent,
    onError,
    onReconnect
  } = options;

  const [state, setState] = useState<SSEState>({
    progress: 0,
    status: 'idle',
    data: null,
    error: null,
    reconnectAttempt: 0,
    isConnected: false
  });

  const esRef = useRef<EventSource | null>(null);
  const reconnectTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const connectionTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const reconnectAttemptRef = useRef(0);
  const isCancelledRef = useRef(false);

  const updateState = useCallback((updates: Partial<SSEState>) => {
    setState(prev => ({ ...prev, ...updates }));
  }, []);

  const cleanup = useCallback(() => {
    if (esRef.current) {
      esRef.current.close();
      esRef.current = null;
    }

    if (reconnectTimeoutRef.current) {
      clearTimeout(reconnectTimeoutRef.current);
      reconnectTimeoutRef.current = null;
    }

    if (connectionTimeoutRef.current) {
      clearTimeout(connectionTimeoutRef.current);
      connectionTimeoutRef.current = null;
    }
  }, []);

  const connect = useCallback((isReconnect = false) => {
    if (isCancelledRef.current || !url) return;

    cleanup();

    if (isReconnect) {
      const currentAttempt = reconnectAttemptRef.current + 1;
      reconnectAttemptRef.current = currentAttempt;
      updateState({ 
        status: 'reconnecting',
        error: null,
        reconnectAttempt: currentAttempt
      });
      onReconnect?.(currentAttempt);
    } else {
      reconnectAttemptRef.current = 0;
      updateState({ 
        status: 'connecting',
        error: null,
        reconnectAttempt: 0
      });
    }

    const es = new EventSource(url);
    esRef.current = es;

    // Connection timeout
    connectionTimeoutRef.current = setTimeout(() => {
      if (es.readyState === EventSource.CONNECTING) {
        es.close();
        updateState({
          status: 'failed',
          error: 'Connection timeout',
          isConnected: false
        });
      }
    }, timeout);

    // Connection opened
    es.onopen = () => {
      if (connectionTimeoutRef.current) {
        clearTimeout(connectionTimeoutRef.current);
        connectionTimeoutRef.current = null;
      }

      updateState({
        status: 'running',
        isConnected: true,
        error: null,
        reconnectAttempt: 0
      });
    };

    // Handle standard progress events
    es.addEventListener('progress', (e: MessageEvent) => {
      try {
        const payload = JSON.parse(e.data);
        updateState(prev => ({ 
          ...prev,
          progress: typeof payload.progress === 'number' ? payload.progress : prev.progress 
        }));
        onEvent?.('progress', payload);
      } catch (error) {
        console.warn('Failed to parse progress event data:', error);
      }
    });

    // Handle completion events
    es.addEventListener('completed', (e: MessageEvent) => {
      try {
        const payload = JSON.parse(e.data);
        updateState({
          status: 'completed',
          data: payload,
          progress: 100,
          isConnected: false
        });
        onEvent?.('completed', payload);
      } catch (error) {
        console.warn('Failed to parse completed event data:', error);
        updateState({
          status: 'completed',
          data: e.data,
          progress: 100,
          isConnected: false
        });
      }
      es.close();
    });

    // Handle failure events
    es.addEventListener('failed', (e: MessageEvent) => {
      try {
        const payload = JSON.parse(e.data);
        updateState({
          status: 'failed',
          error: payload.error || 'Operation failed',
          isConnected: false
        });
        onEvent?.('failed', payload);
      } catch (error) {
        updateState({
          status: 'failed',
          error: 'Operation failed',
          isConnected: false
        });
      }
      es.close();
    });

    // Handle custom events (debates, updates, notifications, etc.)
    ['debate_update', 'agent_response', 'consensus_reached', 'error', 'warning', 'info'].forEach(eventType => {
      es.addEventListener(eventType, (e: MessageEvent) => {
        try {
          const payload = JSON.parse(e.data);
          onEvent?.(eventType, payload);
        } catch (error) {
          console.warn(`Failed to parse ${eventType} event data:`, error);
          onEvent?.(eventType, { raw: e.data });
        }
      });
    });

    // Handle workspace-specific events for real-time collaboration
    [
      'workspace_debate_progress', 'workspace_debate_completed', 'workspace_user_join',
      'workspace_user_leave', 'workspace_user_activity', 'workspace_document_change',
      'workspace_analysis_update', 'workspace_template_progress', 'workspace_template_completed',
      'workspace_system_event', 'workspace_workspace_updated', 'workspace_member_added',
      'workspace_member_removed', 'workspace_role_changed'
    ].forEach(eventType => {
      es.addEventListener(eventType, (e: MessageEvent) => {
        try {
          const payload = JSON.parse(e.data);
          // Handle specific workspace events
          if (eventType === 'workspace_debate_progress' && payload.eventData?.progress) {
            updateState(prev => ({ 
              ...prev,
              progress: typeof payload.eventData.progress === 'number' ? payload.eventData.progress : prev.progress 
            }));
          }
          onEvent?.(eventType, payload);
        } catch (error) {
          console.warn(`Failed to parse ${eventType} event data:`, error);
          onEvent?.(eventType, { raw: e.data });
        }
      });
    });

    // Handle heartbeat events for connection monitoring
    es.addEventListener('heartbeat', (e: MessageEvent) => {
      try {
        const payload = JSON.parse(e.data);
        // Update connection state if needed
        updateState({ isConnected: true });
        onEvent?.('heartbeat', payload);
      } catch (error) {
        // Heartbeat might not have JSON data, just acknowledge it
        updateState({ isConnected: true });
      }
    });

    // Handle connection errors and reconnection
    es.onerror = (error: Event) => {
      console.warn('SSE connection error:', error);
      onError?.(error);

      const currentAttempt = reconnectAttemptRef.current;
      const shouldReconnect = currentAttempt < reconnectAttempts && 
                             !isCancelledRef.current;

      if (shouldReconnect) {
        updateState({
          isConnected: false
        });

        reconnectTimeoutRef.current = setTimeout(() => {
          connect(true);
        }, reconnectDelay * Math.pow(2, currentAttempt)); // Exponential backoff
      } else {
        updateState({
          status: 'failed',
          error: 'Connection failed after multiple attempts',
          isConnected: false
        });
      }
    };
  }, [url, timeout, reconnectAttempts, reconnectDelay, onEvent, onError, onReconnect, cleanup, updateState]);

  const cancel = useCallback(() => {
    isCancelledRef.current = true;
    cleanup();
    updateState({
      status: 'idle',
      isConnected: false,
      error: null
    });
  }, [cleanup, updateState]);

  const retry = useCallback(() => {
    isCancelledRef.current = false;
    reconnectAttemptRef.current = 0;
    updateState({
      reconnectAttempt: 0,
      error: null
    });
    connect(false);
  }, [connect, updateState]);

  useEffect(() => {
    if (!url) {
      updateState({ status: 'idle' });
      return;
    }

    isCancelledRef.current = false;
    connect(false);

    return () => {
      isCancelledRef.current = true;
      cleanup();
    };
  }, [url, connect, cleanup, updateState]);

  return {
    ...state,
    cancel,
    retry,
    isConnecting: state.status === 'connecting',
    isReconnecting: state.status === 'reconnecting',
    canRetry: state.status === 'failed' && !isCancelledRef.current
  };
}

// Enhanced hook for debate-specific SSE events
export function useDebateSSE(url: string, options: SSEOptions = {}) {
  const [debateState, setDebateState] = useState({
    activeAgents: [] as string[],
    currentRound: 0,
    totalRounds: 0,
    consensusLevel: 0,
    lastAgentResponse: null as any,
    debatePhase: 'initializing' as 'initializing' | 'debating' | 'consensus' | 'complete'
  });

  const enhancedOptions = {
    ...options,
    onEvent: (event: string, data: any) => {
      options.onEvent?.(event, data);

      // Handle debate-specific events
      switch (event) {
        case 'debate_update':
          setDebateState(prev => ({
            ...prev,
            activeAgents: data.activeAgents || prev.activeAgents,
            currentRound: data.currentRound || prev.currentRound,
            totalRounds: data.totalRounds || prev.totalRounds,
            consensusLevel: data.consensusLevel || prev.consensusLevel,
            debatePhase: data.phase || prev.debatePhase
          }));
          break;
        case 'agent_response':
          setDebateState(prev => ({
            ...prev,
            lastAgentResponse: data
          }));
          break;
        case 'consensus_reached':
          setDebateState(prev => ({
            ...prev,
            debatePhase: 'complete',
            consensusLevel: 100
          }));
          break;
      }
    }
  };

  const sseResult = useSSE(url, enhancedOptions);

  return {
    ...sseResult,
    debate: debateState
  };
}

