import type { Request, Response, NextFunction } from "express";
import type { User, WorkspaceMember, SystemUserRole, WorkspaceRole } from "@shared/schema";
import { storage } from "../storage";

// Extend User interface to ensure required fields for RBAC
interface RequestUser extends User {
  id: string;
  role: string;
}

// Define user roles hierarchy (higher number = more permissions)
// IMPORTANT: These must match the roles used in shared/schema.ts and getSystemPermissions()
export const USER_ROLES = {
  user: 1,           // Basic user (default role in schema)
  premium_user: 2,   // Premium individual user
  viewer: 1,         // Workspace role
  member: 2,         // Workspace role
  admin: 3,          // System or workspace admin
  owner: 4,          // Workspace owner
  system_admin: 5    // System-wide admin
} as const;

// Define system-wide permissions
export const SYSTEM_PERMISSIONS = {
  CREATE_WORKSPACE: "create_workspace",
  MANAGE_USERS: "manage_users",
  VIEW_AUDIT_LOGS: "view_audit_logs",
  MANAGE_BILLING: "manage_billing",
  ADMIN_DASHBOARD: "admin_dashboard"
} as const;

// Define workspace-level permissions
export const WORKSPACE_PERMISSIONS = {
  READ_WORKSPACE: "read_workspace",
  UPDATE_WORKSPACE: "update_workspace",
  DELETE_WORKSPACE: "delete_workspace",
  MANAGE_MEMBERS: "manage_members",
  INVITE_MEMBERS: "invite_members",
  CREATE_SESSIONS: "create_sessions",
  DELETE_SESSIONS: "delete_sessions",
  MANAGE_TEMPLATES: "manage_templates",
  EXPORT_DATA: "export_data",
  VIEW_ANALYTICS: "view_analytics",
  MANAGE_INTEGRATIONS: "manage_integrations"
} as const;

export type SystemPermission = typeof SYSTEM_PERMISSIONS[keyof typeof SYSTEM_PERMISSIONS];
export type WorkspacePermission = typeof WORKSPACE_PERMISSIONS[keyof typeof WORKSPACE_PERMISSIONS];

// Extend Request interface to include user and workspace context
declare global {
  namespace Express {
    interface Request {
      user?: User;
      workspace?: any;
      workspaceMembership?: WorkspaceMember;
    }
  }
}

/**
 * Check if user has required system-level role
 */
export function hasSystemRole(userRole: string, requiredRole: SystemUserRole): boolean {
  const userRoleLevel = USER_ROLES[userRole as SystemUserRole] || 0;
  const requiredRoleLevel = USER_ROLES[requiredRole];
  return userRoleLevel >= requiredRoleLevel;
}

/**
 * Check if user has required workspace-level role
 */
export function hasWorkspaceRole(membershipRole: string, requiredRole: WorkspaceRole): boolean {
  const memberRoleLevel = USER_ROLES[membershipRole as WorkspaceRole] || 0;
  const requiredRoleLevel = USER_ROLES[requiredRole];
  return memberRoleLevel >= requiredRoleLevel;
}

/**
 * Get user's system permissions based on their role
 * SECURITY CRITICAL: This determines what system-level actions users can perform
 */
export function getSystemPermissions(userRole: string): SystemPermission[] {
  const permissions: SystemPermission[] = [];

  switch (userRole) {
    case "system_admin":
      // System admins have all permissions
      permissions.push(
        SYSTEM_PERMISSIONS.CREATE_WORKSPACE,
        SYSTEM_PERMISSIONS.MANAGE_USERS,
        SYSTEM_PERMISSIONS.VIEW_AUDIT_LOGS,
        SYSTEM_PERMISSIONS.MANAGE_BILLING,
        SYSTEM_PERMISSIONS.ADMIN_DASHBOARD
      );
      break;
    case "admin":
      // Regular admins have most permissions but not user management
      permissions.push(
        SYSTEM_PERMISSIONS.CREATE_WORKSPACE,
        SYSTEM_PERMISSIONS.VIEW_AUDIT_LOGS,
        SYSTEM_PERMISSIONS.MANAGE_BILLING,
        SYSTEM_PERMISSIONS.ADMIN_DASHBOARD
      );
      break;
    case "premium_user":
      // Premium users can create workspaces
      permissions.push(SYSTEM_PERMISSIONS.CREATE_WORKSPACE);
      break;
    case "user":
    default:
      // Basic users have no special system permissions
      break;
  }

  return permissions;
}

/**
 * Get user's workspace permissions based on their membership role
 */
export function getWorkspacePermissions(membershipRole: string): WorkspacePermission[] {
  const permissions: WorkspacePermission[] = [];

  switch (membershipRole) {
    case "owner":
      permissions.push(
        WORKSPACE_PERMISSIONS.READ_WORKSPACE,
        WORKSPACE_PERMISSIONS.UPDATE_WORKSPACE,
        WORKSPACE_PERMISSIONS.DELETE_WORKSPACE,
        WORKSPACE_PERMISSIONS.MANAGE_MEMBERS,
        WORKSPACE_PERMISSIONS.INVITE_MEMBERS,
        WORKSPACE_PERMISSIONS.CREATE_SESSIONS,
        WORKSPACE_PERMISSIONS.DELETE_SESSIONS,
        WORKSPACE_PERMISSIONS.MANAGE_TEMPLATES,
        WORKSPACE_PERMISSIONS.EXPORT_DATA,
        WORKSPACE_PERMISSIONS.VIEW_ANALYTICS
      );
      break;
    case "admin":
      permissions.push(
        WORKSPACE_PERMISSIONS.READ_WORKSPACE,
        WORKSPACE_PERMISSIONS.UPDATE_WORKSPACE,
        WORKSPACE_PERMISSIONS.MANAGE_MEMBERS,
        WORKSPACE_PERMISSIONS.INVITE_MEMBERS,
        WORKSPACE_PERMISSIONS.CREATE_SESSIONS,
        WORKSPACE_PERMISSIONS.DELETE_SESSIONS,
        WORKSPACE_PERMISSIONS.MANAGE_TEMPLATES,
        WORKSPACE_PERMISSIONS.EXPORT_DATA,
        WORKSPACE_PERMISSIONS.VIEW_ANALYTICS
      );
      break;
    case "member":
      permissions.push(
        WORKSPACE_PERMISSIONS.READ_WORKSPACE,
        WORKSPACE_PERMISSIONS.CREATE_SESSIONS,
        WORKSPACE_PERMISSIONS.EXPORT_DATA
      );
      break;
    case "viewer":
      permissions.push(WORKSPACE_PERMISSIONS.READ_WORKSPACE);
      break;
    default:
      // No permissions for unknown roles
      break;
  }

  return permissions;
}

/**
 * Middleware to require authentication
 */
export function requireAuth(req: Request, res: Response, next: NextFunction) {
  if (!req.user) {
    return res.status(401).json({ 
      error: "Authentication required",
      code: "AUTH_REQUIRED" 
    });
  }
  next();
}

/**
 * Middleware to require specific system role
 */
export function requireSystemRole(requiredRole: SystemUserRole) {
  return (req: Request, res: Response, next: NextFunction) => {
    if (!req.user) {
      return res.status(401).json({ 
        error: "Authentication required",
        code: "AUTH_REQUIRED" 
      });
    }

    if (!hasSystemRole((req.user as RequestUser).role, requiredRole)) {
      return res.status(403).json({ 
        error: "Insufficient permissions",
        code: "INSUFFICIENT_PERMISSIONS",
        required: requiredRole,
        current: (req.user as RequestUser).role
      });
    }

    next();
  };
}

/**
 * Middleware to require specific system permission
 */
export function requireSystemPermission(permission: SystemPermission) {
  return (req: Request, res: Response, next: NextFunction) => {
    if (!req.user) {
      return res.status(401).json({ 
        error: "Authentication required",
        code: "AUTH_REQUIRED" 
      });
    }

    const userPermissions = getSystemPermissions((req.user as RequestUser).role);
    if (!userPermissions.includes(permission)) {
      return res.status(403).json({ 
        error: "Insufficient permissions",
        code: "INSUFFICIENT_PERMISSIONS",
        required: permission,
        userRole: (req.user as RequestUser).role
      });
    }

    next();
  };
}

/**
 * Middleware to load workspace context and check access
 */
export function requireWorkspaceAccess(requiredRole?: WorkspaceRole) {
  return async (req: Request, res: Response, next: NextFunction) => {
    try {
      if (!req.user) {
        return res.status(401).json({ 
          error: "Authentication required",
          code: "AUTH_REQUIRED" 
        });
      }

      // Get workspace ID from params, body, or query
      const workspaceId = req.params.workspaceId || req.body.workspaceId || req.query.workspaceId;

      if (!workspaceId) {
        return res.status(400).json({ 
          error: "Workspace ID required",
          code: "WORKSPACE_ID_REQUIRED" 
        });
      }

      // Load workspace
      const workspace = await storage.getWorkspace(workspaceId);
      if (!workspace) {
        return res.status(404).json({ 
          error: "Workspace not found",
          code: "WORKSPACE_NOT_FOUND" 
        });
      }

      // Load user's membership in this workspace
      const membership = await storage.getWorkspaceMembership(workspaceId, (req.user as RequestUser).id);
      if (!membership) {
        return res.status(403).json({ 
          error: "Access denied to workspace",
          code: "WORKSPACE_ACCESS_DENIED" 
        });
      }

      // Check role requirement if specified
      if (requiredRole && !hasWorkspaceRole(membership.role, requiredRole)) {
        return res.status(403).json({ 
          error: "Insufficient workspace permissions",
          code: "INSUFFICIENT_WORKSPACE_PERMISSIONS",
          required: requiredRole,
          current: membership.role
        });
      }

      // Add workspace context to request
      req.workspace = workspace;
      req.workspaceMembership = membership;

      next();
    } catch (error) {
      console.error('Workspace access check failed:', error);
      res.status(500).json({ 
        error: "Internal server error",
        code: "INTERNAL_ERROR" 
      });
    }
  };
}

/**
 * Middleware to require specific workspace permission
 */
export function requireWorkspacePermission(permission: WorkspacePermission) {
  return async (req: Request, res: Response, next: NextFunction) => {
    try {
      if (!req.user) {
        return res.status(401).json({ 
          error: "Authentication required",
          code: "AUTH_REQUIRED" 
        });
      }

      if (!req.workspaceMembership) {
        // Try to load workspace membership if not already loaded
        const workspaceId = req.params.workspaceId || req.body.workspaceId || req.query.workspaceId;
        if (!workspaceId) {
          return res.status(400).json({ 
            error: "Workspace context required",
            code: "WORKSPACE_CONTEXT_REQUIRED" 
          });
        }

        const membership = await storage.getWorkspaceMembership(workspaceId, (req.user as RequestUser).id);
        if (!membership) {
          return res.status(403).json({ 
            error: "Access denied to workspace",
            code: "WORKSPACE_ACCESS_DENIED" 
          });
        }
        req.workspaceMembership = membership;
      }

      const userPermissions = getWorkspacePermissions(req.workspaceMembership.role);
      if (!userPermissions.includes(permission)) {
        return res.status(403).json({ 
          error: "Insufficient workspace permissions",
          code: "INSUFFICIENT_WORKSPACE_PERMISSIONS",
          required: permission,
          userRole: req.workspaceMembership.role
        });
      }

      next();
    } catch (error) {
      console.error('Workspace permission check failed:', error);
      res.status(500).json({ 
        error: "Internal server error",
        code: "INTERNAL_ERROR" 
      });
    }
  };
}

/**
 * Middleware to check if user can access specific resource (like own data)
 */
export function requireResourceAccess(resourceUserIdField = 'userId') {
  return (req: Request, res: Response, next: NextFunction) => {
    if (!req.user) {
      return res.status(401).json({ 
        error: "Authentication required",
        code: "AUTH_REQUIRED" 
      });
    }

    // System admins can access any resource
    if (hasSystemRole((req.user as RequestUser).role, 'admin')) {
      return next();
    }

    // Check if user is accessing their own resource
    const resourceUserId = req.params[resourceUserIdField] || req.body[resourceUserIdField];
    if (resourceUserId && resourceUserId !== (req.user as RequestUser).id) {
      return res.status(403).json({ 
        error: "Access denied to resource",
        code: "RESOURCE_ACCESS_DENIED" 
      });
    }

    next();
  };
}

server/utils/permissions.ts.content:
import type { User, WorkspaceMember, Subscription, Entitlement } from "@shared/schema";
import { storage } from "../storage";
import { 
  USER_ROLES, 
  getSystemPermissions, 
  getWorkspacePermissions,
  hasSystemRole,
  hasWorkspaceRole,
  type UserRole,
  type SystemPermission,
  type WorkspacePermission
} from "../middleware/rbac";
import { 
  BILLING_FEATURES, 
  PLAN_FEATURES, 
  PLAN_LIMITS,
  hasFeatureAccess,
  checkPlanLimit,
  getWorkspaceFeatures,
  type BillingFeature,
  type SubscriptionPlan
} from "../middleware/entitlements";

export interface PermissionContext {
  user: User;
  workspace?: any;
  workspaceMembership?: WorkspaceMember;
  subscription?: Subscription;
  entitlements?: Entitlement[];
}

export interface PermissionResult {
  allowed: boolean;
  reason?: string;
  code?: string;
  metadata?: any;
}

/**
 * Comprehensive permission checker class
 */
export class PermissionChecker {
  private context: PermissionContext;

  constructor(context: PermissionContext) {
    this.context = context;
  }

  /**
   * Check if user has system-level permission
   */
  canPerformSystemAction(permission: SystemPermission): PermissionResult {
    if (!this.context.user) {
      return {
        allowed: false,
        reason: "Authentication required",
        code: "AUTH_REQUIRED"
      };
    }

    const userPermissions = getSystemPermissions(this.context.user.role);
    const allowed = userPermissions.includes(permission);

    return {
      allowed,
      reason: allowed ? undefined : "Insufficient system permissions",
      code: allowed ? undefined : "INSUFFICIENT_SYSTEM_PERMISSIONS",
      metadata: {
        userRole: this.context.user.role,
        requiredPermission: permission
      }
    };
  }

  /**
   * Check if user has workspace-level permission
   */
  canPerformWorkspaceAction(permission: WorkspacePermission): PermissionResult {
    if (!this.context.user) {
      return {
        allowed: false,
        reason: "Authentication required",
        code: "AUTH_REQUIRED"
      };
    }

    if (!this.context.workspaceMembership) {
      return {
        allowed: false,
        reason: "Workspace membership required",
        code: "WORKSPACE_ACCESS_DENIED"
      };
    }

    const memberPermissions = getWorkspacePermissions(this.context.workspaceMembership.role);
    const allowed = memberPermissions.includes(permission);

    return {
      allowed,
      reason: allowed ? undefined : "Insufficient workspace permissions",
      code: allowed ? undefined : "INSUFFICIENT_WORKSPACE_PERMISSIONS",
      metadata: {
        membershipRole: this.context.workspaceMembership.role,
        requiredPermission: permission
      }
    };
  }

  /**
   * Check if user can access a specific billing feature
   */
  async canUseFeature(feature: BillingFeature): Promise<PermissionResult> {
    if (!this.context.user) {
      return {
        allowed: false,
        reason: "Authentication required",
        code: "AUTH_REQUIRED"
      };
    }

    if (!this.context.workspace) {
      return {
        allowed: false,
        reason: "Workspace context required",
        code: "WORKSPACE_CONTEXT_REQUIRED"
      };
    }

    try {
      const hasAccess = await hasFeatureAccess(this.context.workspace.id, feature);

      return {
        allowed: hasAccess,
        reason: hasAccess ? undefined : "Feature requires upgrade",
        code: hasAccess ? undefined : "FEATURE_REQUIRES_UPGRADE",
        metadata: {
          feature,
          workspaceId: this.context.workspace.id,
          plan: this.context.subscription?.plan || 'free'
        }
      };
    } catch (error) {
      return {
        allowed: false,
        reason: "Feature access check failed",
        code: "INTERNAL_ERROR"
      };
    }
  }

  /**
   * Check if user can create more of a specific resource
   */
  async canCreateResource(resource: keyof typeof PLAN_LIMITS.free, getCurrentUsage: () => Promise<number>): Promise<PermissionResult> {
    if (!this.context.user) {
      return {
        allowed: false,
        reason: "Authentication required",
        code: "AUTH_REQUIRED"
      };
    }

    if (!this.context.workspace) {
      return {
        allowed: false,
        reason: "Workspace context required",
        code: "WORKSPACE_CONTEXT_REQUIRED"
      };
    }

    try {
      const currentUsage = await getCurrentUsage();
      const limitCheck = await checkPlanLimit(this.context.workspace.id, resource, currentUsage);

      return {
        allowed: limitCheck.allowed,
        reason: limitCheck.allowed ? undefined : "Plan limit exceeded",
        code: limitCheck.allowed ? undefined : "PLAN_LIMIT_EXCEEDED",
        metadata: {
          resource,
          limit: limitCheck.limit,
          usage: limitCheck.usage,
          workspaceId: this.context.workspace.id
        }
      };
    } catch (error) {
      return {
        allowed: false,
        reason: "Resource limit check failed",
        code: "INTERNAL_ERROR"
      };
    }
  }

  /**
   * Check if user can access specific resource owned by another user
   */
  canAccessUserResource(resourceUserId: string): PermissionResult {
    if (!this.context.user) {
      return {
        allowed: false,
        reason: "Authentication required",
        code: "AUTH_REQUIRED"
      };
    }

    // Users can always access their own resources
    if (this.context.user.id === resourceUserId) {
      return { allowed: true };
    }

    // System admins can access any resource
    if (hasSystemRole(this.context.user.role, 'admin')) {
      return { 
        allowed: true,
        metadata: { accessType: 'admin_override' }
      };
    }

    // Workspace admins can access resources within their workspace
    if (this.context.workspaceMembership && hasWorkspaceRole(this.context.workspaceMembership.role, 'admin')) {
      return { 
        allowed: true,
        metadata: { accessType: 'workspace_admin' }
      };
    }

    return {
      allowed: false,
      reason: "Access denied to resource",
      code: "RESOURCE_ACCESS_DENIED",
      metadata: {
        resourceUserId,
        currentUserId: this.context.user.id
      }
    };
  }

  /**
   * Check if user can manage billing for workspace
   */
  canManageBilling(): PermissionResult {
    if (!this.context.user) {
      return {
        allowed: false,
        reason: "Authentication required",
        code: "AUTH_REQUIRED"
      };
    }

    if (!this.context.workspaceMembership) {
      return {
        allowed: false,
        reason: "Workspace membership required",
        code: "WORKSPACE_ACCESS_DENIED"
      };
    }

    // Only workspace owners can manage billing
    const allowed = this.context.workspaceMembership.role === 'owner';

    return {
      allowed,
      reason: allowed ? undefined : "Only workspace owners can manage billing",
      code: allowed ? undefined : "BILLING_OWNER_REQUIRED",
      metadata: {
        membershipRole: this.context.workspaceMembership.role
      }
    };
  }

  /**
   * Get complete permission summary for user
   */
  async getPermissionSummary(): Promise<{
    systemPermissions: SystemPermission[];
    workspacePermissions: WorkspacePermission[];
    availableFeatures: BillingFeature[];
    planLimits: any;
    canManageBilling: boolean;
  }> {
    const systemPermissions = this.context.user ? getSystemPermissions(this.context.user.role) : [];
    const workspacePermissions = this.context.workspaceMembership ? getWorkspacePermissions(this.context.workspaceMembership.role) : [];

    let availableFeatures: BillingFeature[] = [];
    let planLimits: any = {};

    if (this.context.workspace) {
      availableFeatures = await getWorkspaceFeatures(this.context.workspace.id);
      // Note: getWorkspaceLimits would need to be implemented
      // planLimits = await getWorkspaceLimits(this.context.workspace.id);
    }

    const billingPermission = this.canManageBilling();

    return {
      systemPermissions,
      workspacePermissions,
      availableFeatures,
      planLimits,
      canManageBilling: billingPermission.allowed
    };
  }
}

/**
 * Factory function to create PermissionChecker with loaded context
 */
export async function createPermissionChecker(
  user: User,
  workspaceId?: string
): Promise<PermissionChecker> {
  const context: PermissionContext = { user };

  if (workspaceId) {
    try {
      // Load workspace context
      const workspace = await storage.getWorkspace(workspaceId);
      if (workspace) {
        context.workspace = workspace;
      }

      // Load workspace membership
      const membership = await storage.getWorkspaceMembership(workspaceId, user.id);
      if (membership) {
        context.workspaceMembership = membership;
      }

      // Load subscription
      const subscription = await storage.getWorkspaceSubscription(workspaceId);
      if (subscription) {
        context.subscription = subscription;
      }

      // Load entitlements
      const entitlements = await storage.getWorkspaceEntitlements(workspaceId);
      context.entitlements = entitlements;

    } catch (error) {
      console.error('Failed to load workspace context for permission checker:', error);
    }
  }

  return new PermissionChecker(context);
}

/**
 * Utility functions for common permission checks
 */
export const PermissionUtils = {
  /**
   * Quick check if user can perform system action
   */
  async canUserPerformSystemAction(user: User, permission: SystemPermission): Promise<boolean> {
    const checker = new PermissionChecker({ user });
    const result = checker.canPerformSystemAction(permission);
    return result.allowed;
  },

  /**
   * Quick check if user can perform workspace action
   */
  async canUserPerformWorkspaceAction(
    user: User, 
    workspaceId: string, 
    permission: WorkspacePermission
  ): Promise<boolean> {
    try {
      const checker = await createPermissionChecker(user, workspaceId);
      const result = checker.canPerformWorkspaceAction(permission);
      return result.allowed;
    } catch (error) {
      console.error('Workspace permission check failed:', error);
      return false;
    }
  },

  /**
   * Quick check if user can use feature
   */
  async canUserUseFeature(user: User, workspaceId: string, feature: BillingFeature): Promise<boolean> {
    try {
      const checker = await createPermissionChecker(user, workspaceId);
      const result = await checker.canUseFeature(feature);
      return result.allowed;
    } catch (error) {
      console.error('Feature access check failed:', error);
      return false;
    }
  },

  /**
   * Quick check if user can access resource
   */
  async canUserAccessResource(user: User, resourceUserId: string, workspaceId?: string): Promise<boolean> {
    try {
      const checker = await createPermissionChecker(user, workspaceId);
      const result = checker.canAccessUserResource(resourceUserId);
      return result.allowed;
    } catch (error) {
      console.error('Resource access check failed:', error);
      return false;
    }
  },

  /**
   * Get user's effective permissions for workspace
   */
  async getUserWorkspacePermissions(user: User, workspaceId: string): Promise<{
    role: string;
    permissions: WorkspacePermission[];
    features: BillingFeature[];
  }> {
    try {
      const checker = await createPermissionChecker(user, workspaceId);
      const summary = await checker.getPermissionSummary();

      return {
        role: checker.context.workspaceMembership?.role || 'none',
        permissions: summary.workspacePermissions,
        features: summary.availableFeatures
      };
    } catch (error) {
      console.error('Failed to get user workspace permissions:', error);
      return {
        role: 'none',
        permissions: [],
        features: []
      };
    }
  }
};

