    print_test "FAIL" "✗ Database connection not configured"
fi

# 3. Session management
if [ ! -z "$SESSION_SECRET" ] || [ "$NODE_ENV" != "production" ]; then
    print_test "PASS" "✓ Session management configured"
    ((readiness_score++))
else
