    id: string;
    content: string;
    timestamp: number;
    source: string;
  }>;
  correspondenceMap: Array<{
    tupleIndex: number;
    role: string;
    policyApplied: boolean;
    contextWeight: number;
  }>;
  constraints: Array<{
    type: string;
    value: string;
    enforced: boolean;
  }>;
}

interface MultiRaterScore {
  raterId: string;
  score: number;
  reliability?: number;
}

interface ValidatorResult {
